        "file": "static/admin/js/core.js",
        "code": "// Core JavaScript helper functions\r\n'use strict';\r\n\r\n// quickElement(tagType, parentReference [, textInChildNode, attribute, attributeValue ...]);\r\nfunction quickElement() {\r\n    const obj = document.createElement(arguments[0]);\r\n    if (arguments[2]) {\r\n        const textNode = document.createTextNode(arguments[2]);\r\n        obj.appendChild(textNode);\r\n    }\r\n    const len = arguments.length;\r\n    for (let i = 3; i < len; i += 2) {\r\n        obj.setAttribute(arguments[i], arguments[i + 1]);\r\n    }\r\n    arguments[1].appendChild(obj);\r\n    return obj;\r\n}\r\n\r\n// \"a\" is reference to an object\r\nfunction removeChildren(a) {\r\n    while (a.hasChildNodes()) {\r\n        a.removeChild(a.lastChild);\r\n    }\r\n}\r\n\r\n// ----------------------------------------------------------------------------\r\n// Find-position functions by PPK\r\n// See https://www.quirksmode.org/js/findpos.html\r\n// ----------------------------------------------------------------------------\r\nfunction findPosX(obj) {\r\n    let curleft = 0;\r\n    if (obj.offsetParent) {\r\n        while (obj.offsetParent) {\r\n            curleft += obj.offsetLeft - obj.scrollLeft;\r\n            obj = obj.offsetParent;\r\n        }\r\n    } else if (obj.x) {\r\n        curleft += obj.x;\r\n    }\r\n    return curleft;\r\n}\r\n\r\nfunction findPosY(obj) {\r\n    let curtop = 0;\r\n    if (obj.offsetParent) {\r\n        while (obj.offsetParent) {\r\n            curtop += obj.offsetTop - obj.scrollTop;\r\n            obj = obj.offsetParent;\r\n        }\r\n    } else if (obj.y) {\r\n        curtop += obj.y;\r\n    }\r\n    return curtop;\r\n}\r\n\r\n//-----------------------------------------------------------------------------\r\n// Date object extensions\r\n// ----------------------------------------------------------------------------\r\n{\r\n    Date.prototype.getTwelveHours = function() {\r\n        return this.getHours() % 12 || 12;\r\n    };\r\n\r\n    Date.prototype.getTwoDigitMonth = function() {\r\n        return (this.getMonth() < 9) ? '0' + (this.getMonth() + 1) : (this.getMonth() + 1);\r\n    };\r\n\r\n    Date.prototype.getTwoDigitDate = function() {\r\n        return (this.getDate() < 10) ? '0' + this.getDate() : this.getDate();\r\n    };\r\n\r\n    Date.prototype.getTwoDigitTwelveHour = function() {\r\n        return (this.getTwelveHours() < 10) ? '0' + this.getTwelveHours() : this.getTwelveHours();\r\n    };\r\n\r\n    Date.prototype.getTwoDigitHour = function() {\r\n        return (this.getHours() < 10) ? '0' + this.getHours() : this.getHours();\r\n    };\r\n\r\n    Date.prototype.getTwoDigitMinute = function() {\r\n        return (this.getMinutes() < 10) ? '0' + this.getMinutes() : this.getMinutes();\r\n    };\r\n\r\n    Date.prototype.getTwoDigitSecond = function() {\r\n        return (this.getSeconds() < 10) ? '0' + this.getSeconds() : this.getSeconds();\r\n    };\r\n\r\n    Date.prototype.getAbbrevDayName = function() {\r\n        return typeof window.CalendarNamespace === \"undefined\"\r\n            ? '0' + this.getDay()\r\n            : window.CalendarNamespace.daysOfWeekAbbrev[this.getDay()];\r\n    };\r\n\r\n    Date.prototype.getFullDayName = function() {\r\n        return typeof window.CalendarNamespace === \"undefined\"\r\n            ? '0' + this.getDay()\r\n            : window.CalendarNamespace.daysOfWeek[this.getDay()];\r\n    };\r\n\r\n    Date.prototype.getAbbrevMonthName = function() {\r\n        return typeof window.CalendarNamespace === \"undefined\"\r\n            ? this.getTwoDigitMonth()\r\n            : window.CalendarNamespace.monthsOfYearAbbrev[this.getMonth()];\r\n    };\r\n\r\n    Date.prototype.getFullMonthName = function() {\r\n        return typeof window.CalendarNamespace === \"undefined\"\r\n            ? this.getTwoDigitMonth()\r\n            : window.CalendarNamespace.monthsOfYear[this.getMonth()];\r\n    };\r\n\r\n    Date.prototype.strftime = function(format) {\r\n        const fields = {\r\n            a: this.getAbbrevDayName(),\r\n            A: this.getFullDayName(),\r\n            b: this.getAbbrevMonthName(),\r\n            B: this.getFullMonthName(),\r\n            c: this.toString(),\r\n            d: this.getTwoDigitDate(),\r\n            H: this.getTwoDigitHour(),\r\n            I: this.getTwoDigitTwelveHour(),\r\n            m: this.getTwoDigitMonth(),\r\n            M: this.getTwoDigitMinute(),\r\n            p: (this.getHours() >= 12) ? 'PM' : 'AM',\r\n            S: this.getTwoDigitSecond(),\r\n            w: '0' + this.getDay(),\r\n            x: this.toLocaleDateString(),\r\n            X: this.toLocaleTimeString(),\r\n            y: ('' + this.getFullYear()).substr(2, 4),\r\n            Y: '' + this.getFullYear(),\r\n            '%': '%'\r\n        };\r\n        let result = '', i = 0;\r\n        while (i < format.length) {\r\n            if (format.charAt(i) === '%') {\r\n                result += fields[format.charAt(i + 1)];\r\n                ++i;\r\n            }\r\n            else {\r\n                result += format.charAt(i);\r\n            }\r\n            ++i;\r\n        }\r\n        return result;\r\n    };\r\n\r\n    // ----------------------------------------------------------------------------\r\n    // String object extensions\r\n    // ----------------------------------------------------------------------------\r\n    String.prototype.strptime = function(format) {\r\n        const split_format = format.split(/[.\\-/]/);\r\n        const date = this.split(/[.\\-/]/);\r\n        let i = 0;\r\n        let day, month, year;\r\n        while (i < split_format.length) {\r\n            switch (split_format[i]) {\r\n            case \"%d\":\r\n                day = date[i];\r\n                break;\r\n            case \"%m\":\r\n                month = date[i] - 1;\r\n                break;\r\n            case \"%Y\":\r\n                year = date[i];\r\n                break;\r\n            case \"%y\":\r\n                // A %y value in the range of [00, 68] is in the current\r\n                // century, while [69, 99] is in the previous century,\r\n                // according to the Open Group Specification.\r\n                if (parseInt(date[i], 10) >= 69) {\r\n                    year = date[i];\r\n                } else {\r\n                    year = (new Date(Date.UTC(date[i], 0))).getUTCFullYear() + 100;\r\n                }\r\n                break;\r\n            }\r\n            ++i;\r\n        }\r\n        // Create Date object from UTC since the parsed value is supposed to be\r\n        // in UTC, not local time. Also, the calendar uses UTC functions for\r\n        // date extraction.\r\n        return new Date(Date.UTC(year, month, day));\r\n    };\r\n}\r\n",
