        "file": "static/css/ui.css",
        "code": "@charset \"UTF-8\";\r\n/* ==== BASE STYLES ====*/\r\n/* ==================== GLOBAL STYLES ======================= */\r\n@import url(\"https://rsms.me/inter/inter.css\");\r\nhtml {\r\n  font-family: \"Inter\", sans-serif;\r\n  font-size: 15px;\r\n}\r\n\r\n/* ========================\r\nINCLUDE STYLES AND COMPONENTS\r\n===================== */\r\n/* ================== HELPERS  =================== */\r\na:hover {\r\n  text-decoration: none;\r\n}\r\n\r\n.img-wrap {\r\n  text-align: center;\r\n  display: block;\r\n}\r\n.img-wrap img {\r\n  max-width: 100%;\r\n}\r\n\r\n.icon-wrap {\r\n  text-align: center;\r\n  display: inline-block;\r\n}\r\n\r\n.price-wrap {\r\n  letter-spacing: -0.7px;\r\n}\r\n\r\n.content-body {\r\n  flex: 1 1 auto;\r\n  padding: 2rem 2.3rem;\r\n}\r\n\r\n/* =================  DEFINED VARIABLES =================== */\r\n.icon-xs, .icon-sm, .icon-md, .icon-lg {\r\n  display: inline-block;\r\n  text-align: center;\r\n  flex-shrink: 0;\r\n  flex-grow: 0;\r\n}\r\n\r\n.icon-xs {\r\n  width: 32px;\r\n  height: 32px;\r\n  line-height: 32px !important;\r\n  font-size: 16px;\r\n}\r\n\r\n.icon-sm {\r\n  width: 48px;\r\n  height: 48px;\r\n  line-height: 48px !important;\r\n  font-size: 20px;\r\n}\r\n\r\n.icon-md {\r\n  width: 60px;\r\n  height: 60px;\r\n  line-height: 60px !important;\r\n  font-size: 28px;\r\n}\r\n\r\n.icon-lg {\r\n  width: 96px;\r\n  height: 96px;\r\n  line-height: 96px !important;\r\n  font-size: 42px;\r\n}\r\n\r\n.img-xs, .img-sm, .img-md, .img-lg {\r\n  -o-object-fit: cover;\r\n     object-fit: cover;\r\n  flex-shrink: 0;\r\n  flex-grow: 0;\r\n}\r\n\r\n.img-xs {\r\n  width: 40px;\r\n  height: 40px;\r\n}\r\n\r\n.img-sm {\r\n  width: 80px;\r\n  height: 80px;\r\n}\r\n\r\n.img-md {\r\n  width: 140px;\r\n  height: 140px;\r\n}\r\n\r\n.img-lg {\r\n  width: 250px;\r\n  height: 250px;\r\n}\r\n\r\n.center-xy {\r\n  top: 50%;\r\n  left: 50%;\r\n  position: absolute;\r\n  transform: translate(-50%, -50%);\r\n}\r\n\r\n.center-y {\r\n  top: 50%;\r\n  position: absolute;\r\n  transform: translateY(-50%);\r\n}\r\n\r\n.center-x {\r\n  left: 50%;\r\n  position: absolute;\r\n  transform: translateX(-50%);\r\n}\r\n\r\n.vh-100 {\r\n  height: 100vh;\r\n}\r\n\r\n.overflow-h {\r\n  overflow: hidden;\r\n}\r\n\r\n.flip-h {\r\n  transform: scaleX(-1);\r\n}\r\n\r\n.opacity {\r\n  opacity: 0.5;\r\n}\r\n\r\n[class*=hover-] {\r\n  transition: 0.5s;\r\n}\r\n\r\n.hover-bg:hover {\r\n  background: #3167eb;\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, #3167eb, #3167eb);\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.hover-zoom:hover {\r\n  transition: 0.5s;\r\n  transform: scaleX(1);\r\n}\r\n\r\n/* ============== spacing ============== */\r\n.padding-y {\r\n  padding-top: 40px;\r\n  padding-bottom: 40px;\r\n}\r\n\r\n.padding-top {\r\n  padding-top: 40px;\r\n}\r\n\r\n.padding-bottom {\r\n  padding-bottom: 40px;\r\n}\r\n\r\n.padding-y-lg {\r\n  padding-top: 80px;\r\n  padding-bottom: 80px;\r\n}\r\n\r\n.padding-top-lg {\r\n  padding-top: 80px;\r\n}\r\n\r\n.padding-bottom-lg {\r\n  padding-bottom: 80px;\r\n}\r\n\r\n.padding-y-sm {\r\n  padding-top: 20px;\r\n  padding-bottom: 20px;\r\n}\r\n\r\n.padding-top-sm {\r\n  padding-top: 20px;\r\n}\r\n\r\n.padding-bottom-sm {\r\n  padding-bottom: 20px;\r\n}\r\n\r\n.relative {\r\n  position: relative;\r\n}\r\n\r\n.absolute {\r\n  position: absolute;\r\n}\r\n\r\nvar {\r\n  font-style: normal;\r\n}\r\n\r\nfigure {\r\n  margin-bottom: 0;\r\n}\r\n\r\n.form-noborder input, .form-noborder select, .form-noborder .btn {\r\n  border: 0;\r\n}\r\n.form-noborder select.form-control-lg:not([size]):not([multiple]) {\r\n  height: 2.875rem;\r\n}\r\n\r\n/* all clearfix */\r\narticle:after,\r\n.form-group:after {\r\n  display: block;\r\n  clear: both;\r\n  content: \"\";\r\n}\r\n\r\n/* -------------------- small grid gutter --------------------- */\r\n.row-sm {\r\n  margin-right: -7px;\r\n  margin-left: -7px;\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.row-sm > [class^=col] {\r\n  padding-left: 7px;\r\n  padding-right: 7px;\r\n}\r\n\r\n.bg {\r\n  background-color: #f8f9fa;\r\n}\r\n\r\n.bg-white {\r\n  background-color: #fff;\r\n}\r\n\r\n.bg-orange {\r\n  background-color: #ff9017;\r\n}\r\n\r\n.bg-green {\r\n  background-color: #00b517;\r\n}\r\n\r\n.bg-blue {\r\n  background-color: #3167eb;\r\n}\r\n\r\n.bg-red {\r\n  background-color: #fa3434;\r\n}\r\n\r\n.bg-gradient-blue {\r\n  background: rgba(33, 37, 41, 0.4);\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, rgba(49, 103, 235, 0.9), rgba(33, 37, 41, 0.4));\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.bg-gradient-green {\r\n  background: rgba(33, 37, 41, 0.4);\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, rgba(0, 181, 23, 0.9), rgba(33, 37, 41, 0.4));\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.bg-gradient-orange {\r\n  background: rgba(33, 37, 41, 0.4);\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, rgba(255, 144, 23, 0.9), rgba(33, 37, 41, 0.4));\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.bg-gradient-red {\r\n  background: rgba(33, 37, 41, 0.4);\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, rgba(250, 52, 52, 0.9), rgba(33, 37, 41, 0.4));\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.bg-gradient-pink {\r\n  background: rgba(33, 37, 41, 0.4);\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, rgba(232, 62, 140, 0.9), rgba(33, 37, 41, 0.4));\r\n  /* Standard syntax */\r\n  transition: 0.5s;\r\n}\r\n\r\n.bg-pattern {\r\n  background-image: url(../images/banners/bg-pattern.svg), linear-gradient(135deg, #3167eb, #545454);\r\n  background-size: cover, auto;\r\n  background-repeat: no-repeat, repeat;\r\n  background-position: 0px 0px, 50% 50%;\r\n}\r\n\r\n.bg-img {\r\n  overflow: hidden;\r\n  background-color: #ddd;\r\n  background-image: linear-gradient(135deg, rgba(49, 103, 235, 0.8), rgba(84, 84, 84, 0.9)), url(\"../images/banners/bg-cpu.jpg\");\r\n  background-position: 0px 0px, 50% 50%;\r\n  background-size: auto cover;\r\n}\r\n\r\n.overlay-gradient {\r\n  position: relative;\r\n}\r\n.overlay-gradient:before {\r\n  position: absolute;\r\n  content: \"\";\r\n  display: block;\r\n  top: 0;\r\n  left: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  opacity: 0.6;\r\n  transition: 0.5s;\r\n  background: aqua;\r\n  /* For browsers that do not support gradients */\r\n  /* For Safari 5.1 to 6.0 */\r\n  /* For Opera 11.1 to 12.0 */\r\n  /* For Firefox 3.6 to 15 */\r\n  background: linear-gradient(to bottom right, #3167eb, aqua);\r\n  /* Standard syntax */\r\n}\r\n.overlay-gradient:hover:before {\r\n  opacity: 0.9;\r\n}\r\n\r\n/* --------------------- titles ---------------------- */\r\n.section-heading {\r\n  margin-bottom: 20px;\r\n  margin-top: 15px;\r\n}\r\n\r\n.section-title {\r\n  color: #212529;\r\n}\r\n\r\n.title-text {\r\n  margin-top: 30\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
