        "file": "templates/accounts/dashboard.html",
        "code": "{% extends 'base.html' %}\r\n\r\n{% block content %}\r\n\r\n<!-- ========================= SECTION CONTENT ========================= -->\r\n<section class=\"section-conten padding-y bg\">\r\n    {% include 'includes/alerts.html' %}\r\n    <div class=\"container\">\r\n        <div class=\"row\">\r\n        {% include 'includes/dashboard_sidebar.html' %}\r\n        <main class=\"col-md-9\">\r\n            <article class=\"card\">\r\n                <header class=\"card-header\">\r\n                    <strong class=\"d-inline-block mr-3\">Logged in as:</strong>\r\n                    <span>{{user.full_name}}</span>\r\n                </header>\r\n                <div class=\"card-body\">\r\n                    <div class=\"row\"> \r\n                        <div class=\"col-md-6\">\r\n                            <div class=\"card\" style=\"text-align: center;\">\r\n                                <div class=\"card-body\">\r\n                                    <h5 class=\"card-title\">Total Orders</h5>\r\n                                    <h4>{{orders_count}}</h4>\r\n                                    <a href=\"{% url 'my_orders' %}\">View Orders</a>\r\n                                </div>\r\n                            </div>\r\n                        </div> \r\n                        <div class=\"col-md-6\">\r\n                            <div class=\"card\" style=\"text-align: center;\">\r\n                                <div class=\"card-body\">\r\n                                    <img src=\"{{userprofile.profile_picture.url}}\" alt=\"User Profile Picture\" width=\"50\" height=\"50\" style=\"border-radius: 50%;\">\r\n                                    <p class=\"mb-0\">{{user.email}}</p>\r\n                                    <p>{{user.phone_number}}</p>\r\n                                </div>\r\n                            </div>\r\n                        </div>                      \r\n                    </div> <!-- row.// -->\r\n                </div> <!-- card-body .// -->\r\n            </article> <!-- order-group.// --> \r\n        </main>\r\n    </div> <!-- row.// -->\r\n    </div>    \r\n    \r\n</section>\r\n<!-- ========================= SECTION CONTENT END// ========================= -->\r\n\r\n{% endblock %}",
