        "file": "foodOnline/static/js/scripts.js",
        "code": "/*!\r\n * SlickNav Responsive Mobile Menu v1.0.4\r\n * (c) 2015 Josh Cope\r\n * licensed under MIT\r\n */\r\n;\r\n(function ($, document, window) {\r\n    var\r\n            // default settings object.\r\n            defaults = {\r\n                label: 'MENU',\r\n                duplicate: true,\r\n                duration: 300,\r\n                easingOpen: 'swing',\r\n                easingClose: 'swing',\r\n                closedSymbol: '<i class=\"icon-keyboard_arrow_right\"></i>',\r\n                openedSymbol: '<i class=\"icon-keyboard_arrow_down\"></i>',\r\n                prependTo: '.main-nav',\r\n                appendTo: '',\r\n                parentTag: 'a',\r\n                closeOnClick: false,\r\n                allowParentLinks: true,\r\n                nestedParentLinks: true,\r\n                showChildren: false,\r\n                removeIds: false,\r\n                removeClasses: false,\r\n                removeStyles: false,\r\n                brand: '',\r\n                init: function () {},\r\n                beforeOpen: function () {},\r\n                beforeClose: function () {},\r\n                afterOpen: function () {},\r\n                afterClose: function () {}\r\n            },\r\n    mobileMenu = 'slicknav',\r\n            prefix = 'slicknav';\r\n\r\n    function Plugin(element, options) {\r\n        this.element = element;\r\n\r\n        // jQuery has an extend method which merges the contents of two or\r\n        // more objects, storing the result in the first object. The first object\r\n        // is generally empty as we don't want to alter the default options for\r\n        // future instances of the plugin\r\n        this.settings = $.extend({}, defaults, options);\r\n\r\n        this._defaults = defaults;\r\n        this._name = mobileMenu;\r\n\r\n        this.init();\r\n    }\r\n\r\n    Plugin.prototype.init = function () {\r\n        var $this = this,\r\n                menu = $(this.element),\r\n                settings = this.settings,\r\n                iconClass,\r\n                menuBar;\r\n\r\n        // clone menu if needed\r\n        if (settings.duplicate) {\r\n            $this.mobileNav = menu.clone();\r\n            //remove ids from clone to prevent css issues\r\n            $this.mobileNav.removeAttr('id');\r\n            $this.mobileNav.find('*').each(function (i, e) {\r\n                $(e).removeAttr('id');\r\n            });\r\n        } else {\r\n            $this.mobileNav = menu;\r\n\r\n            // remove ids if set\r\n            $this.mobileNav.removeAttr('id');\r\n            $this.mobileNav.find('*').each(function (i, e) {\r\n                $(e).removeAttr('id');\r\n            });\r\n        }\r\n\r\n        // remove classes if set\r\n        if (settings.removeClasses) {\r\n            $this.mobileNav.removeAttr('class');\r\n            $this.mobileNav.find('*').each(function (i, e) {\r\n                $(e).removeAttr('class');\r\n            });\r\n        }\r\n\r\n        // remove styles if set\r\n        if (settings.removeStyles) {\r\n            $this.mobileNav.removeAttr('style');\r\n            $this.mobileNav.find('*').each(function (i, e) {\r\n                $(e).removeAttr('style');\r\n            });\r\n        }\r\n\r\n        // styling class for the button\r\n        iconClass = prefix + '_icon';\r\n\r\n        if (settings.label === '') {\r\n            iconClass += ' ' + prefix + '_no-text';\r\n        }\r\n\r\n        if (settings.parentTag == 'a') {\r\n            settings.parentTag = 'a href=\"#\"';\r\n        }\r\n\r\n        // create menu bar\r\n        $this.mobileNav.attr('class', prefix + '_nav');\r\n        menuBar = $('<div class=\"' + prefix + '_menu\"></div>');\r\n        if (settings.brand !== '') {\r\n            var brand = $('<div class=\"' + prefix + '_brand\">' + settings.brand + '</div>');\r\n            $(menuBar).append(brand);\r\n        }\r\n        $this.btn = $(\r\n                ['<' + settings.parentTag + ' aria-haspopup=\"true\" tabindex=\"0\" class=\"' + prefix + '_btn ' + prefix + '_collapsed\">',\r\n                    '<span class=\"' + prefix + '_menutxt\">' + settings.label + '</span>',\r\n                    '<span class=\"' + iconClass + '\">',\r\n                    '<span class=\"' + prefix + '_icon-bar\"></span>',\r\n                    '<span class=\"' + prefix + '_icon-bar\"></span>',\r\n                    '<span class=\"' + prefix + '_icon-bar\"></span>',\r\n                    '</span>',\r\n                    '</' + settings.parentTag + '>'\r\n                ].join('')\r\n                );\r\n        $(menuBar).append($this.btn);\r\n        if (settings.appendTo !== '') {\r\n            $(settings.appendTo).append(menuBar);\r\n        } else {\r\n            $(settings.prependTo).prepend(menuBar);\r\n        }\r\n        menuBar.append($this.mobileNav);\r\n\r\n        // iterate over structure adding additional structure\r\n        var items = $this.mobileNav.find('li');\r\n        $(items).each(function () {\r\n            var item = $(this),\r\n                    data = {};\r\n            data.children = item.children('ul').attr('role', 'menu');\r\n            item.data('menu', data);\r\n\r\n            // if a list item has a nested menu\r\n            if (data.children.length > 0) {\r\n\r\n                // select all text before the child menu\r\n                // check for anchors\r\n\r\n                var a = item.contents(),\r\n                        containsAnchor = false,\r\n                        nodes = [];\r\n\r\n                $(a).each(function () {\r\n                    if (!$(this).is('ul')) {\r\n                        nodes.push(this);\r\n                    } else {\r\n                        return false;\r\n                    }\r\n\r\n                    if ($(this).is(\"a\")) {\r\n                        containsAnchor = true;\r\n                    }\r\n                });\r\n\r\n                var wrapElement = $(\r\n                        '<' + settings.parentTag + ' role=\"menuitem\" aria-haspopup=\"true\" tabindex=\"-1\" class=\"' + prefix + '_item\"/>'\r\n                        );\r\n\r\n                // wrap item text with tag and add classes unless we are separating parent links\r\n                if ((!settings.allowParentLinks || settings.nestedParentLinks) || !containsAnchor) {\r\n                    var $wrap = $(nodes).wrapAll(wrapElement).parent();\r\n                    $wrap.addClass(prefix + '_row');\r\n                } else\r\n                    $(nodes).wrapAll('<span class=\"' + prefix + '_parent-link ' + prefix + '_row\"/>').parent();\r\n\r\n                if (!settings.showChildren) {\r\n                    item.addClass(prefix + '_collapsed');\r\n                } else {\r\n                    item.addClass(prefix + '_open');\r\n                }\r\n\r\n                item.addClass(prefix + '_parent');\r\n\r\n                // create parent arrow. wrap with link if parent links and separating\r\n                var arrowElement = $('<span class=\"' + prefix + '_arrow\">' + (settings.showChildren ? settings.openedSymbol : settings.closedSymbol) + '</span>');\r\n\r\n                if (settings.allowParentLinks && !settings.nestedParentLinks && containsAnchor)\r\n                    arrowElement = arrowElement.wrap(wrapElement).parent();\r\n\r\n   \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: foodOnline/static/js/scripts.js",
          "GitHub: https://github.com/CanonEngineer/FoodOnlineDjango/blob/main/foodOnline/static/js/scripts.js"
        ]
