        "file": "orders/forms.py",
        "code": "from django import forms\r\nfrom . models import Order\r\n\r\nclass OrderForm(forms.ModelForm):\r\n    class Meta:\r\n        model = Order\r\n        fields = ['first_name', 'last_name', 'phone', 'email', 'address', 'country', 'state', 'city', 'pin_code']\r\n",
