        "file": "public/admin/plugins/timepicker/bootstrap-timepicker.js",
        "code": "//TODO: move arrow styles and button click code into configurable items, with defaults matching the existing code\r\n\r\n/*!\r\n* Timepicker Component for Twitter Bootstrap\r\n*\r\n* Copyright 2013 Joris de Wit\r\n*\r\n* Contributors https://github.com/jdewit/bootstrap-timepicker/graphs/contributors\r\n*\r\n* For the full copyright and license information, please view the LICENSE\r\n* file that was distributed with this source code.\r\n*/\r\n(function($, window, document, undefined) {\r\n  'use strict';\r\n\r\n  // TIMEPICKER PUBLIC CLASS DEFINITION\r\n  var Timepicker = function(element, options) {\r\n    this.widget = '';\r\n    this.$element = $(element);\r\n    this.defaultTime = options.defaultTime;\r\n    this.disableFocus = options.disableFocus;\r\n    this.isOpen = options.isOpen;\r\n    this.minuteStep = options.minuteStep;\r\n    this.modalBackdrop = options.modalBackdrop;\r\n    this.secondStep = options.secondStep;\r\n    this.showInputs = options.showInputs;\r\n    this.showMeridian = options.showMeridian;\r\n    this.showSeconds = options.showSeconds;\r\n    this.template = options.template;\r\n    this.appendWidgetTo = options.appendWidgetTo;\r\n\tthis.upArrowStyle = options.upArrowStyle;\r\n\tthis.downArrowStyle = options.downArrowStyle;\r\n\tthis.containerClass = options.containerClass;\r\n\r\n    this._init();\r\n  };\r\n\r\n  Timepicker.prototype = {\r\n\r\n    constructor: Timepicker,\r\n\r\n    _init: function() {\r\n      var self = this;\r\n\r\n      if (this.$element.parent().hasClass('input-append') || this.$element.parent().hasClass('input-prepend')) {\r\n\t\tif (this.$element.parent('.input-append, .input-prepend').find('.add-on').length) {\r\n\t\t\tthis.$element.parent('.input-append, .input-prepend').find('.add-on').on({\r\n\t\t\t  'click.timepicker': $.proxy(this.showWidget, this)\r\n\t\t\t});\t\t\r\n\t\t} else {\r\n\t\t\tthis.$element.closest(this.containerClass).find('.add-on').on({\r\n\t\t\t  'click.timepicker': $.proxy(this.showWidget, this)\r\n\t\t\t});\t\t\r\n\t\t}\r\n\t\t\r\n        this.$element.on({\r\n          'focus.timepicker': $.proxy(this.highlightUnit, this),\r\n          'click.timepicker': $.proxy(this.highlightUnit, this),\r\n          'keydown.timepicker': $.proxy(this.elementKeydown, this),\r\n          'blur.timepicker': $.proxy(this.blurElement, this)\r\n        });\r\n      } else {\r\n        if (this.template) {\r\n          this.$element.on({\r\n            'focus.timepicker': $.proxy(this.showWidget, this),\r\n            'click.timepicker': $.proxy(this.showWidget, this),\r\n            'blur.timepicker': $.proxy(this.blurElement, this)\r\n          });\r\n        } else {\r\n          this.$element.on({\r\n            'focus.timepicker': $.proxy(this.highlightUnit, this),\r\n            'click.timepicker': $.proxy(this.highlightUnit, this),\r\n            'keydown.timepicker': $.proxy(this.elementKeydown, this),\r\n            'blur.timepicker': $.proxy(this.blurElement, this)\r\n          });\r\n        }\r\n      }\r\n\r\n      if (this.template !== false) {\r\n        this.$widget = $(this.getTemplate()).prependTo(this.$element.parents(this.appendWidgetTo)).on('click', $.proxy(this.widgetClick, this));\r\n      } else {\r\n        this.$widget = false;\r\n      }\r\n\r\n      if (this.showInputs && this.$widget !== false) {\r\n        this.$widget.find('input').each(function() {\r\n          $(this).on({\r\n            'click.timepicker': function() { $(this).select(); },\r\n            'keydown.timepicker': $.proxy(self.widgetKeydown, self)\r\n          });\r\n        });\r\n      }\r\n\r\n      this.setDefaultTime(this.defaultTime);\r\n    },\r\n\r\n    blurElement: function() {\r\n      this.highlightedUnit = undefined;\r\n      this.updateFromElementVal();\r\n    },\r\n\r\n    decrementHour: function() {\r\n      if (this.showMeridian) {\r\n        if (this.hour === 1) {\r\n          this.hour = 12;\r\n        } else if (this.hour === 12) {\r\n          this.hour--;\r\n\r\n          return this.toggleMeridian();\r\n        } else if (this.hour === 0) {\r\n          this.hour = 11;\r\n\r\n          return this.toggleMeridian();\r\n        } else {\r\n          this.hour--;\r\n        }\r\n      } else {\r\n        if (this.hour === 0) {\r\n          this.hour = 23;\r\n        } else {\r\n          this.hour--;\r\n        }\r\n      }\r\n      this.update();\r\n    },\r\n\r\n    decrementMinute: function(step) {\r\n      var newVal;\r\n\r\n      if (step) {\r\n        newVal = this.minute - step;\r\n      } else {\r\n        newVal = this.minute - this.minuteStep;\r\n      }\r\n\r\n      if (newVal < 0) {\r\n        this.decrementHour();\r\n        this.minute = newVal + 60;\r\n      } else {\r\n        this.minute = newVal;\r\n      }\r\n      this.update();\r\n    },\r\n\r\n    decrementSecond: function() {\r\n      var newVal = this.second - this.secondStep;\r\n\r\n      if (newVal < 0) {\r\n        this.decrementMinute(true);\r\n        this.second = newVal + 60;\r\n      } else {\r\n        this.second = newVal;\r\n      }\r\n      this.update();\r\n    },\r\n\r\n    elementKeydown: function(e) {\r\n      switch (e.keyCode) {\r\n      case 9: //tab\r\n        this.updateFromElementVal();\r\n\r\n        switch (this.highlightedUnit) {\r\n        case 'hour':\r\n          e.preventDefault();\r\n          this.highlightNextUnit();\r\n          break;\r\n        case 'minute':\r\n          if (this.showMeridian || this.showSeconds) {\r\n            e.preventDefault();\r\n            this.highlightNextUnit();\r\n          }\r\n          break;\r\n        case 'second':\r\n          if (this.showMeridian) {\r\n            e.preventDefault();\r\n            this.highlightNextUnit();\r\n          }\r\n          break;\r\n        }\r\n        break;\r\n      case 27: // escape\r\n        this.updateFromElementVal();\r\n        break;\r\n      case 37: // left arrow\r\n        e.preventDefault();\r\n        this.highlightPrevUnit();\r\n        this.updateFromElementVal();\r\n        break;\r\n      case 38: // up arrow\r\n        e.preventDefault();\r\n        switch (this.highlightedUnit) {\r\n        case 'hour':\r\n          this.incrementHour();\r\n          this.highlightHour();\r\n          break;\r\n        case 'minute':\r\n          this.incrementMinute();\r\n          this.highlightMinute();\r\n          break;\r\n        case 'second':\r\n          this.incrementSecond();\r\n          this.highlightSecond();\r\n          break;\r\n        case 'meridian':\r\n          this.toggleMeridian();\r\n          this.highlightMeridian();\r\n          break;\r\n        }\r\n        break;\r\n      case 39: // right arrow\r\n        e.preventDefault();\r\n        this.updateFromElementVal();\r\n        this.highlightNextUnit();\r\n        break;\r\n      case 40: // down arrow\r\n        e.preventDefault();\r\n        switch (this.highlightedUnit) {\r\n        case 'hour':\r\n          this.decrementHour();\r\n          this.highlightHour();\r\n          break;\r\n        case 'minute':\r\n          this.decrementMinute();\r\n          this.highlightMinute();\r\n          break;\r\n        case 'second':\r\n          this.decrementSecond();\r\n          this.highlightSecond();\r\n          break;\r\n        case 'meridian':\r\n          this.toggleMeridian();\r\n          this.highlightMeridian();\r\n          break;\r\n        }\r\n        break;\r\n      }\r\n    },\r\n\r\n    formatTime: function(hour, mi\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
