        "file": "views/admin/emails.ejs",
        "code": "<%- include('inc/header') -%>\r\n\r\n    <!-- Content Wrapper. Contains page content -->\r\n    <div class=\"content-wrapper\">\r\n        <!-- Content Header (Page header) -->\r\n        <section class=\"content-header\">\r\n            <h1>\r\n                E-mails\r\n            </h1>\r\n            <ol class=\"breadcrumb\">\r\n                <li><a href=\"/\"><i class=\"fa fa-home\"></i> Home</a></li>\r\n                <li class=\"active\">E-mails</li>\r\n            </ol>\r\n        </section>\r\n\r\n        <!-- Main content -->\r\n        <section class=\"content container-fluid\">\r\n\r\n            <div class=\"box\">\r\n                <div class=\"box-header\">\r\n                    <h3 class=\"box-title\">Lista</h3>\r\n                </div>\r\n                <!-- /.box-header -->\r\n                <div class=\"box-body no-padding\">\r\n                    <table class=\"table table-striped table-hover\">\r\n                        <thead>\r\n                            <tr>\r\n                                <th style=\"width: 10px\">#</th>\r\n                                <th>E-mail</th>\r\n                                <th style=\"min-width: 75px;\">Ações</th>\r\n                            </tr>\r\n                        </thead>\r\n                        <tbody>\r\n                            <% data.forEach(function(row){ %>\r\n                            <tr data-row='<%= JSON.stringify(row) %>'>\r\n                                <td><%= row.id %></td>\r\n                                <td><%= row.email %></td>\r\n                                <td><button type=\"button\" class=\"btn btn-xs btn-danger btn-delete\"><i class=\"fa fa-trash\"></i> Excluir</button></td>\r\n                            </tr>\r\n                            <% }); %>\r\n                        </tbody>\r\n                    </table>\r\n                </div>\r\n                <!-- /.box-body -->\r\n            </div>\r\n\r\n        </section>\r\n        <!-- /.content -->\r\n    </div>\r\n    <!-- /.content-wrapper -->\r\n\r\n<%- include('inc/footer') -%>\r\n\r\n<script src=\"/js/hcode-formsave.js\"></script>\r\n<script src=\"/js/hcode-grid.js\"></script>\r\n\r\n<script>\r\n\r\n    new HcodeGrid({\r\n\r\n        deleteUrl:'/admin/emails/${data.id}',\r\n        deleteMsg:'Deseja realmente deletar este e-mail ${data.email}?'\r\n\r\n    });\r\n\r\n</script>",
