        "file": "package.json",
        "code": "{\r\n  \"name\": \"network-scanner\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"Multi-threaded network scanner with professional web interface\",\r\n  \"main\": \"server.js\",\r\n  \"scripts\": {\r\n    \"start\": \"node server.js\",\r\n    \"test\": \"node --test test-platform.js\"\r\n  },\r\n  \"keywords\": [\r\n    \"network\",\r\n    \"scanner\",\r\n    \"ping\",\r\n    \"port-scanner\",\r\n    \"os-detection\",\r\n    \"mac-address\"\r\n  ],\r\n  \"author\": \"Antigravity\",\r\n  \"license\": \"ISC\",\r\n  \"dependencies\": {\r\n    \"exceljs\": \"^4.4.0\",\r\n    \"express\": \"^4.19.2\",\r\n    \"net-snmp\": \"^3.26.3\",\r\n    \"oracledb\": \"^7.0.1\",\r\n    \"pdfkit\": \"^0.19.1\",\r\n    \"ws\": \"^8.16.0\"\r\n  }\r\n}\r\n",
