        "id": "customize-veyon-file-3rdparty-kldap-src-core-ber-cpp",
        "parent": "customize-veyon-grp-3rdparty-kldap-src-core-files-b",
        "layer": "file",
        "title": "ber.cpp",
        "description": "Código-fonte: `3rdparty/kldap/src/core/ber.cpp`",
        "file": "3rdparty/kldap/src/core/ber.cpp",
        "code": "/*\r\n  This file is part of libkldap.\r\n  SPDX-FileCopyrightText: 2004-2006 Szombathelyi György <gyurco@freemail.hu>\r\n\r\n  SPDX-License-Identifier: LGPL-2.0-or-later\r\n*/\r\n\r\n#include \"ber.h\"\r\n#include \"kldap_config.h\"\r\n\r\n#include \"ldap_core_debug.h\"\r\n\r\n#include <QList>\r\n#include <QVarLengthArray>\r\n\r\n#include <cstdarg>\r\n\r\n#if LDAP_FOUND\r\n\r\n#ifdef Q_OS_SOLARIS // krazy:exclude=cpp\r\n#define BC31 1\r\n#endif\r\n\r\n#if !HAVE_WINLDAP_H\r\n#include <lber.h>\r\n#include <ldap.h>\r\n#else\r\n#include \"w32-ldap-help.h\"\r\n#endif\r\n\r\n#ifndef LBER_USE_DER\r\n#define LBER_USE_DER 1\r\n#endif\r\n\r\n#if !HAVE_BER_MEMFREE\r\n#if !HAVE_WINLDAP_H\r\n#define ber_memfree(x) ldap_memfree(x)\r\n#else\r\n#define ber_memfree(x) win_ldap_memfree(x)\r\n#endif\r\n#endif\r\n\r\n#endif\r\n\r\nusing namespace KLDAPCore;\r\n\r\nclass Q_DECL_HIDDEN Ber::BerPrivate\r\n{\r\npublic:\r\n#if LDAP_FOUND\r\n    BerElement *mBer = nullptr;\r\n#endif\r\n};\r\n\r\n#if LDAP_FOUND\r\nBer::Ber()\r\n    : d(new BerPrivate)\r\n{\r\n    d->mBer = ber_alloc_t(LBER_USE_DER);\r\n    Q_ASSERT(d->mBer);\r\n}\r\n\r\nBer::Ber(const QByteArray &value)\r\n    : d(new BerPrivate)\r\n{\r\n    struct berval bv;\r\n    bv.bv_val = (char *)value.data();\r\n    bv.bv_len = value.size();\r\n    d->mBer = ber_init(&bv);\r\n    Q_ASSERT(d->mBer);\r\n}\r\n\r\nBer::~Ber()\r\n{\r\n    ber_free(d->mBer, 1);\r\n}\r\n\r\nBer::Ber(const Ber &that)\r\n    : d(new BerPrivate)\r\n{\r\n    struct berval *bv;\r\n    if (ber_flatten(that.d->mBer, &bv) == 0) {\r\n        d->mBer = ber_init(bv);\r\n        ber_bvfree(bv);\r\n    }\r\n}\r\n\r\nBer &Ber::operator=(const Ber &that)\r\n{\r\n    if (this == &that) {\r\n        return *this;\r\n    }\r\n\r\n    struct berval *bv;\r\n    if (ber_flatten(that.d->mBer, &bv) == 0) {\r\n        ber_free(d->mBer, 1);\r\n        d->mBer = ber_init(bv);\r\n        ber_bvfree(bv);\r\n    }\r\n    return *this;\r\n}\r\n\r\nQByteArray Ber::flatten() const\r\n{\r\n    QByteArray ret;\r\n    struct berval *bv;\r\n    if (ber_flatten(d->mBer, &bv) == 0) {\r\n        ret = QByteArray(bv->bv_val, bv->bv_len);\r\n        ber_bvfree(bv);\r\n    }\r\n    return ret;\r\n}\r\n\r\nint Ber::printf(QString format, ...)\r\n{\r\n    char fmt[2];\r\n    va_list args;\r\n    va_start(args, format);\r\n    fmt[1] = '\\0';\r\n\r\n    int i = 0;\r\n    int ret = 0;\r\n    while (i < format.length()) {\r\n        fmt[0] = format[i].toLatin1();\r\n        i++;\r\n        switch (fmt[0]) {\r\n        case 'b':\r\n        case 'e':\r\n        case 'i': {\r\n            ber_int_t v = va_arg(args, int);\r\n            ret = ber_printf(d->mBer, fmt, v);\r\n            break;\r\n        }\r\n        case 'B': {\r\n            // FIXME: QBitArray would be logical, but how to access the bits?\r\n            QByteArray *B = va_arg(args, QByteArray *);\r\n            int Bc = va_arg(args, int);\r\n            ret = ber_printf(d->mBer, fmt, B->data(), Bc);\r\n            break;\r\n        }\r\n        case 'o': {\r\n            QByteArray *o = va_arg(args, QByteArray *);\r\n            ret = ber_printf(d->mBer, fmt, o->data(), o->size());\r\n            break;\r\n        }\r\n        case 'O': {\r\n            QByteArray *O = va_arg(args, QByteArray *);\r\n            struct berval bv;\r\n            bv.bv_val = (char *)O->data();\r\n            bv.bv_len = O->size();\r\n            ret = ber_printf(d->mBer, fmt, &bv);\r\n            break;\r\n        }\r\n        case 's': {\r\n            QByteArray *s = va_arg(args, QByteArray *);\r\n            ret = ber_printf(d->mBer, fmt, s->data());\r\n            break;\r\n            break;\r\n        }\r\n        case 't': {\r\n            unsigned int t = va_arg(args, unsigned int);\r\n            ret = ber_printf(d->mBer, fmt, t);\r\n            break;\r\n        }\r\n        case 'v': {\r\n            QList<QByteArray> *v = va_arg(args, QList<QByteArray> *);\r\n            QVarLengthArray<const char *> l(v->count() + 1);\r\n            int j;\r\n            for (j = 0; j < v->count(); j++) {\r\n                l[j] = v->at(j).data();\r\n            }\r\n            l[j] = nullptr;\r\n            ret = ber_printf(d->mBer, fmt, l.data());\r\n            break;\r\n        }\r\n        case 'V': {\r\n            QList<QByteArray> *V = va_arg(args, QList<QByteArray> *);\r\n            QVarLengthArray<struct berval *> bv(V->count() + 1);\r\n            QVarLengthArray<struct berval> bvs(V->count());\r\n            int j;\r\n            for (j = 0; j < V->count(); j++) {\r\n                bvs[j].bv_val = (char *)V->at(j).data();\r\n                bvs[j].bv_len = V->at(j).size();\r\n                bv[j] = &bvs[j];\r\n            }\r\n            bv[V->count()] = nullptr;\r\n            ret = ber_printf(d->mBer, fmt, bv.data());\r\n            break;\r\n        }\r\n        case 'n':\r\n        case '{':\r\n        case '}':\r\n        case '[':\r\n        case ']':\r\n            ret = ber_printf(d->mBer, fmt);\r\n            break;\r\n        default:\r\n            qCWarning(LDAP_CORE_LOG) << \"Invalid BER format parameter: '\" << fmt << \"'\";\r\n            ret = -1;\r\n        }\r\n        qCDebug(LDAP_CORE_LOG) << \"ber_printf format:\" << fmt << \"ret:\" << ret;\r\n        if (ret == -1) {\r\n            break;\r\n        }\r\n    }\r\n    va_end(args);\r\n    return ret;\r\n}\r\n\r\nint Ber::scanf(QString format, ...)\r\n{\r\n    char fmt[2];\r\n    va_list args;\r\n    va_start(args, format);\r\n    fmt[1] = '\\0';\r\n\r\n    int i = 0;\r\n    int ret = 0;\r\n    while (i < format.length()) {\r\n        fmt[0] = format[i].toLatin1();\r\n        i++;\r\n        switch (fmt[0]) {\r\n        case 'l':\r\n        case 'b':\r\n        case 'e':\r\n        case 'i': {\r\n            int *v = va_arg(args, int *);\r\n            ret = ber_scanf(d->mBer, fmt, v);\r\n            break;\r\n        }\r\n        case 'B': {\r\n            // FIXME: QBitArray would be logical, but how to access the bits?\r\n            QByteArray *B = va_arg(args, QByteArray *);\r\n            int *Bc = va_arg(args, int *);\r\n            char *c;\r\n            ret = ber_scanf(d->mBer, fmt, &c, Bc);\r\n            if (ret != -1) {\r\n                *B = QByteArray(c, (*Bc + 7) / 8);\r\n                ber_memfree(c);\r\n            }\r\n            break;\r\n        }\r\n        case 'o': {\r\n            QByteArray *o = va_arg(args, QByteArray *);\r\n            struct berval bv;\r\n            ret = ber_scanf(d->mBer, fmt, &bv);\r\n            if (ret != -1) {\r\n                *o = QByteArray(bv.bv_val, bv.bv_len);\r\n                ber_memfree(bv.bv_val);\r\n            }\r\n            break;\r\n        }\r\n        case 'O': {\r\n            QByteArray *O = va_arg(args, QByteArray *);\r\n            struct berval *bv;\r\n            ret = ber_scanf(d->mBer, fmt, &bv);\r\n            if (ret != -1) {\r\n                *O = QByteArray(bv->bv_val, bv->bv_len);\r\n                ber_bvfree(bv);\r\n            }\r\n            break;\r\n        }\r\n        case 'm': { // the same as 'O', just *bv should not be freed.\r\n            QByteArray *m = va_arg(args, QByteArray *);\r\n            struct berval *bv;\r\n            ret = ber_scanf(d->mBer, fmt, &bv);\r\n            if (ret != -1) {\r\n                *m = QByteArray(bv->bv_val, bv->bv_len);\r\n            }\r\n            break;\r\n        }\r\n        case 'a': {\r\n            QByteArray *a = va_arg(args, QByteArray *);\r\n            char *c;\r\n            ret = \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: 3rdparty/kldap/src/core/ber.cpp",
          "GitHub: https://github.com/CanonEngineer/CustomizeVeyonProject/blob/main/3rdparty/kldap/src/core/ber.cpp"
        ]
