        "file": "3rdparty/libvncserver/src/common/sha1.c",
        "code": "/**************************** sha1.c ***************************/\r\n/***************** See RFC 6234 for details. *******************/\r\n/* Copyright (c) 2011 IETF Trust and the persons identified as */\r\n/* authors of the code.  All rights reserved.                  */\r\n/* See sha.h for terms of use and redistribution.              */\r\n\r\n/*\r\n *  Description:\r\n *      This file implements the Secure Hash Algorithm SHA-1\r\n *      as defined in the U.S. National Institute of Standards\r\n *      and Technology Federal Information Processing Standards\r\n *      Publication (FIPS PUB) 180-3 published in October 2008\r\n *      and formerly defined in its predecessors, FIPS PUB 180-1\r\n *      and FIP PUB 180-2.\r\n *\r\n *      A combined document showing all algorithms is available at\r\n *              http://csrc.nist.gov/publications/fips/\r\n *                     fips180-3/fips180-3_final.pdf\r\n *\r\n *      The SHA-1 algorithm produces a 160-bit message digest for a\r\n *      given data stream that can serve as a means of providing a\r\n *      \"fingerprint\" for a message.\r\n *\r\n *  Portability Issues:\r\n *      SHA-1 is defined in terms of 32-bit \"words\".  This code\r\n *      uses <stdint.h> (included via \"sha.h\") to define 32- and\r\n *      8-bit unsigned integer types.  If your C compiler does\r\n *      not support 32-bit unsigned integers, this code is not\r\n *      appropriate.\r\n *\r\n *  Caveats:\r\n *      SHA-1 is designed to work with messages less than 2^64 bits\r\n *      long.  This implementation uses SHA1Input() to hash the bits\r\n *      that are a multiple of the size of an 8-bit octet, and then\r\n *      optionally uses SHA1FinalBits() to hash the final few bits of\r\n *      the input.\r\n */\r\n\r\n#include \"sha.h\"\r\n#include \"sha-private.h\"\r\n\r\n/*\r\n *  Define the SHA1 circular left shift macro\r\n */\r\n#define SHA1_ROTL(bits,word) \\\r\n                (((word) << (bits)) | ((word) >> (32-(bits))))\r\n\r\n/*\r\n * Add \"length\" to the length.\r\n * Set Corrupted when overflow has occurred.\r\n */\r\nstatic uint32_t addTemp;\r\n#define SHA1AddLength(context, length)                     \\\r\n    (addTemp = (context)->Length_Low,                      \\\r\n     (context)->Corrupted =                                \\\r\n        (((context)->Length_Low += (length)) < addTemp) && \\\r\n        (++(context)->Length_High == 0) ? shaInputTooLong  \\\r\n                                        : (context)->Corrupted )\r\n\r\n/* Local Function Prototypes */\r\nstatic void SHA1ProcessMessageBlock(SHA1Context *context);\r\nstatic void SHA1Finalize(SHA1Context *context, uint8_t Pad_Byte);\r\nstatic void SHA1PadMessage(SHA1Context *context, uint8_t Pad_Byte);\r\n\r\n/*\r\n *  SHA1Reset\r\n *\r\n *  Description:\r\n *      This function will initialize the SHA1Context in preparation\r\n *      for computing a new SHA1 message digest.\r\n *\r\n *  Parameters:\r\n *      context: [in/out]\r\n *          The context to reset.\r\n *\r\n *  Returns:\r\n *      sha Error Code.\r\n *\r\n */\r\nint SHA1Reset(SHA1Context *context)\r\n{\r\n  if (!context) return shaNull;\r\n\r\n  context->Length_High = context->Length_Low = 0;\r\n  context->Message_Block_Index = 0;\r\n\r\n  /* Initial Hash Values: FIPS 180-3 section 5.3.1 */\r\n  context->Intermediate_Hash[0]   = 0x67452301;\r\n  context->Intermediate_Hash[1]   = 0xEFCDAB89;\r\n  context->Intermediate_Hash[2]   = 0x98BADCFE;\r\n  context->Intermediate_Hash[3]   = 0x10325476;\r\n  context->Intermediate_Hash[4]   = 0xC3D2E1F0;\r\n\r\n  context->Computed   = 0;\r\n  context->Corrupted  = shaSuccess;\r\n\r\n  return shaSuccess;\r\n}\r\n\r\n/*\r\n *  SHA1Input\r\n *\r\n *  Description:\r\n *      This function accepts an array of octets as the next portion\r\n *      of the message.\r\n *\r\n *  Parameters:\r\n *      context: [in/out]\r\n *          The SHA context to update.\r\n *      message_array[ ]: [in]\r\n *          An array of octets representing the next portion of\r\n *          the message.\r\n *      length: [in]\r\n *          The length of the message in message_array.\r\n *\r\n *  Returns:\r\n *      sha Error Code.\r\n *\r\n */\r\nint SHA1Input(SHA1Context *context,\r\n    const uint8_t *message_array, unsigned length)\r\n{\r\n  if (!context) return shaNull;\r\n  if (!length) return shaSuccess;\r\n  if (!message_array) return shaNull;\r\n  if (context->Computed) return context->Corrupted = shaStateError;\r\n  if (context->Corrupted) return context->Corrupted;\r\n\r\n  while (length--) {\r\n    context->Message_Block[context->Message_Block_Index++] =\r\n      *message_array;\r\n\r\n    if ((SHA1AddLength(context, 8) == shaSuccess) &&\r\n      (context->Message_Block_Index == SHA1_Message_Block_Size))\r\n      SHA1ProcessMessageBlock(context);\r\n\r\n    message_array++;\r\n  }\r\n\r\n  return context->Corrupted;\r\n}\r\n\r\n/*\r\n * SHA1FinalBits\r\n *\r\n * Description:\r\n *   This function will add in any final bits of the message.\r\n *\r\n * Parameters:\r\n *   context: [in/out]\r\n *     The SHA context to update.\r\n *   message_bits: [in]\r\n *     The final bits of the message, in the upper portion of the\r\n *     byte.  (Use 0b###00000 instead of 0b00000### to input the\r\n *     three bits ###.)\r\n *   length: [in]\r\n *     The number of bits in message_bits, between 1 and 7.\r\n *\r\n * Returns:\r\n *   sha Error Code.\r\n */\r\nint SHA1FinalBits(SHA1Context *context, uint8_t message_bits,\r\n    unsigned int length)\r\n{\r\n  static uint8_t masks[8] = {\r\n      /* 0 0b00000000 */ 0x00, /* 1 0b10000000 */ 0x80,\r\n      /* 2 0b11000000 */ 0xC0, /* 3 0b11100000 */ 0xE0,\r\n      /* 4 0b11110000 */ 0xF0, /* 5 0b11111000 */ 0xF8,\r\n      /* 6 0b11111100 */ 0xFC, /* 7 0b11111110 */ 0xFE\r\n  };\r\n\r\n  static uint8_t markbit[8] = {\r\n      /* 0 0b10000000 */ 0x80, /* 1 0b01000000 */ 0x40,\r\n      /* 2 0b00100000 */ 0x20, /* 3 0b00010000 */ 0x10,\r\n      /* 4 0b00001000 */ 0x08, /* 5 0b00000100 */ 0x04,\r\n      /* 6 0b00000010 */ 0x02, /* 7 0b00000001 */ 0x01\r\n  };\r\n\r\n  if (!context) return shaNull;\r\n  if (!length) return shaSuccess;\r\n  if (context->Corrupted) return context->Corrupted;\r\n  if (context->Computed) return context->Corrupted = shaStateError;\r\n  if (length >= 8) return context->Corrupted = shaBadParam;\r\n\r\n  SHA1AddLength(context, length);\r\n  SHA1Finalize(context,\r\n    (uint8_t) ((message_bits & masks[length]) | markbit[length]));\r\n\r\n  return context->Corrupted;\r\n}\r\n\r\n/*\r\n * SHA1Result\r\n *\r\n * Description:\r\n *   This function will return the 160-bit message digest\r\n *   into the Message_Digest array provided by the caller.\r\n *   NOTE:\r\n *    The first octet of hash is stored in the element with index 0,\r\n *      the last octet of hash in the element with index 19.\r\n *\r\n * Parameters:\r\n *   context: [in/out]\r\n *     The context to use to calculate the SHA-1 hash.\r\n *   Message_Digest[ ]: [out]\r\n *     Where the digest is returned.\r\n *\r\n * Returns:\r\n *   sha Error Code.\r\n *\r\n */\r\nint SHA1Result(SHA1Context *context,\r\n    uint8_t Message_Digest[SHA1HashSize])\r\n{\r\n  int i;\r\n\r\n  if (!context) return shaNull;\r\n  if (!Message_Digest) return shaNull;\r\n  if (context->Corrupted) return context->Corrupted;\r\n\r\n  if (!context->Computed)\r\n    SHA1Finalize(context, 0x80);\r\n\r\n  for (i = 0; i < SHA1HashSize; ++\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: 3rdparty/libvncserver/src/common/sha1.c",
          "GitHub: https://github.com/CanonEngineer/CustomizeVeyonProject/blob/main/3rdparty/libvncserver/src/common/sha1.c"
        ]
