        "id": "customize-veyon-file-3rdparty-libvncserver-src-libvncserver-rfbregion-c",
        "parent": "customize-veyon-grp-3rdparty-libvncserver-src-libvncserver-files-r-s",
        "layer": "file",
        "title": "rfbregion.c",
        "description": "Código-fonte: `3rdparty/libvncserver/src/libvncserver/rfbregion.c`",
        "file": "3rdparty/libvncserver/src/libvncserver/rfbregion.c",
        "code": "/* -=- sraRegion.c\r\n * Copyright (c) 2001 James \"Wez\" Weatherall, Johannes E. Schindelin\r\n *\r\n * A general purpose region clipping library\r\n * Only deals with rectangular regions, though.\r\n */\r\n\r\n#include <rfb/rfb.h>\r\n#include <rfb/rfbregion.h>\r\n\r\n/* -=- Internal Span structure */\r\n\r\nstruct sraRegion;\r\n\r\ntypedef struct sraSpan {\r\n  struct sraSpan *_next;\r\n  struct sraSpan *_prev;\r\n  int start;\r\n  int end;\r\n  struct sraRegion *subspan;\r\n} sraSpan;\r\n\r\ntypedef struct sraRegion {\r\n  sraSpan front;\r\n  sraSpan back;\r\n} sraSpanList;\r\n\r\n/* -=- Span routines */\r\n\r\nsraSpanList *sraSpanListDup(const sraSpanList *src);\r\nvoid sraSpanListDestroy(sraSpanList *list);\r\n\r\nstatic sraSpan *\r\nsraSpanCreate(int start, int end, const sraSpanList *subspan) {\r\n  sraSpan *item = (sraSpan*)malloc(sizeof(sraSpan));\r\n  if (!item) return NULL;\r\n  item->_next = item->_prev = NULL;\r\n  item->start = start;\r\n  item->end = end;\r\n  item->subspan = sraSpanListDup(subspan);\r\n  return item;\r\n}\r\n\r\nstatic sraSpan *\r\nsraSpanDup(const sraSpan *src) {\r\n  sraSpan *span;\r\n  if (!src) return NULL;\r\n  span = sraSpanCreate(src->start, src->end, src->subspan);\r\n  return span;\r\n}\r\n\r\nstatic void\r\nsraSpanInsertAfter(sraSpan *newspan, sraSpan *after) {\r\n  if(newspan && after) {\r\n    newspan->_next = after->_next;\r\n    newspan->_prev = after;\r\n    after->_next->_prev = newspan;\r\n    after->_next = newspan;\r\n  }\r\n}\r\n\r\nstatic void\r\nsraSpanInsertBefore(sraSpan *newspan, sraSpan *before) {\r\n  if(newspan && before) {\r\n    newspan->_next = before;\r\n    newspan->_prev = before->_prev;\r\n    before->_prev->_next = newspan;\r\n    before->_prev = newspan;\r\n  }\r\n}\r\n\r\nstatic void\r\nsraSpanRemove(sraSpan *span) {\r\n  if(span) {\r\n    span->_prev->_next = span->_next;\r\n    span->_next->_prev = span->_prev;\r\n  }\r\n}\r\n\r\nstatic void\r\nsraSpanDestroy(sraSpan *span) {\r\n  if (span->subspan) sraSpanListDestroy(span->subspan);\r\n  free(span);\r\n}\r\n\r\n#ifdef DEBUG\r\nstatic void\r\nsraSpanCheck(const sraSpan *span, const char *text) {\r\n  /* Check the span is valid! */\r\n  if (span->start == span->end) {\r\n    printf(text); \r\n    printf(\":%d-%d\\n\", span->start, span->end);\r\n  }\r\n}\r\n#endif\r\n\r\n/* -=- SpanList routines */\r\n\r\nstatic void sraSpanPrint(const sraSpan *s);\r\n\r\nstatic void\r\nsraSpanListPrint(const sraSpanList *l) {\r\n  sraSpan *curr;\r\n  if (!l) {\r\n\t  printf(\"NULL\");\r\n\t  return;\r\n  }\r\n  curr = l->front._next;\r\n  printf(\"[\");\r\n  while (curr != &(l->back)) {\r\n    sraSpanPrint(curr);\r\n    curr = curr->_next;\r\n  }\r\n  printf(\"]\");\r\n}\r\n\r\nvoid\r\nsraSpanPrint(const sraSpan *s) {\r\n  printf(\"(%d-%d)\", (s->start), (s->end));\r\n  if (s->subspan)\r\n    sraSpanListPrint(s->subspan);\r\n}\r\n\r\nstatic sraSpanList *\r\nsraSpanListCreate(void) {\r\n  sraSpanList *item = (sraSpanList*)malloc(sizeof(sraSpanList));\r\n  if (!item) return NULL;\r\n  item->front._next = &(item->back);\r\n  item->front._prev = NULL;\r\n  item->back._prev = &(item->front);\r\n  item->back._next = NULL;\r\n  return item;\r\n}\r\n\r\nsraSpanList *\r\nsraSpanListDup(const sraSpanList *src) {\r\n  sraSpanList *newlist;\r\n  sraSpan *newspan, *curr;\r\n\r\n  if (!src) return NULL;\r\n  newlist = sraSpanListCreate();\r\n  curr = src->front._next;\r\n  while (curr != &(src->back)) {\r\n    newspan = sraSpanDup(curr);\r\n    sraSpanInsertBefore(newspan, &(newlist->back));\r\n    curr = curr->_next;\r\n  }\r\n\r\n  return newlist;\r\n}\r\n\r\nvoid\r\nsraSpanListDestroy(sraSpanList *list) {\r\n  sraSpan *curr;\r\n  while (list->front._next != &(list->back)) {\r\n    curr = list->front._next;\r\n    sraSpanRemove(curr);\r\n    sraSpanDestroy(curr);\r\n  }\r\n  free(list);\r\n}\r\n\r\nstatic void\r\nsraSpanListMakeEmpty(sraSpanList *list) {\r\n  sraSpan *curr;\r\n  while (list->front._next != &(list->back)) {\r\n    curr = list->front._next;\r\n    sraSpanRemove(curr);\r\n    sraSpanDestroy(curr);\r\n  }\r\n  list->front._next = &(list->back);\r\n  list->front._prev = NULL;\r\n  list->back._prev = &(list->front);\r\n  list->back._next = NULL;\r\n}\r\n\r\nstatic rfbBool\r\nsraSpanListEqual(const sraSpanList *s1, const sraSpanList *s2) {\r\n  sraSpan *sp1, *sp2;\r\n\r\n  if (!s1) {\r\n    if (!s2) {\r\n      return 1;\r\n    } else {\r\n      rfbErr(\"sraSpanListEqual:incompatible spans (only one NULL!)\\n\");\r\n      return FALSE;\r\n    }\r\n  }\r\n\r\n  sp1 = s1->front._next;\r\n  sp2 = s2->front._next;\r\n  while ((sp1 != &(s1->back)) &&\r\n\t (sp2 != &(s2->back))) {\r\n    if ((sp1->start != sp2->start) ||\r\n\t(sp1->end != sp2->end) ||\r\n\t(!sraSpanListEqual(sp1->subspan, sp2->subspan))) {\r\n      return 0;\r\n    }\r\n    sp1 = sp1->_next;\r\n    sp2 = sp2->_next;\r\n  }\r\n\r\n  if ((sp1 == &(s1->back)) && (sp2 == &(s2->back))) {\r\n    return 1;\r\n  } else {\r\n    return 0;\r\n  }    \r\n}\r\n\r\nstatic rfbBool\r\nsraSpanListEmpty(const sraSpanList *list) {\r\n  return (list->front._next == &(list->back));\r\n}\r\n\r\nstatic unsigned long\r\nsraSpanListCount(const sraSpanList *list) {\r\n  sraSpan *curr = list->front._next;\r\n  unsigned long count = 0;\r\n  while (curr != &(list->back)) {\r\n    if (curr->subspan) {\r\n      count += sraSpanListCount(curr->subspan);\r\n    } else {\r\n      count += 1;\r\n    }\r\n    curr = curr->_next;\r\n  }\r\n  return count;\r\n}\r\n\r\nstatic void\r\nsraSpanMergePrevious(sraSpan *dest) {\r\n  sraSpan *prev = dest->_prev;\r\n \r\n  while ((prev->_prev) &&\r\n\t (prev->end == dest->start) &&\r\n\t (sraSpanListEqual(prev->subspan, dest->subspan))) {\r\n    /*\r\n    printf(\"merge_prev:\");\r\n    sraSpanPrint(prev);\r\n    printf(\" & \");\r\n    sraSpanPrint(dest);\r\n    printf(\"\\n\");\r\n    */\r\n    dest->start = prev->start;\r\n    sraSpanRemove(prev);\r\n    sraSpanDestroy(prev);\r\n    prev = dest->_prev;\r\n  }\r\n}    \r\n\r\nstatic void\r\nsraSpanMergeNext(sraSpan *dest) {\r\n  sraSpan *next = dest->_next;\r\n  while ((next->_next) &&\r\n\t (next->start == dest->end) &&\r\n\t (sraSpanListEqual(next->subspan, dest->subspan))) {\r\n/*\r\n\t  printf(\"merge_next:\");\r\n    sraSpanPrint(dest);\r\n    printf(\" & \");\r\n    sraSpanPrint(next);\r\n    printf(\"\\n\");\r\n\t*/\r\n    dest->end = next->end;\r\n    sraSpanRemove(next);\r\n    sraSpanDestroy(next);\r\n    next = dest->_next;\r\n  }\r\n}\r\n\r\nstatic void\r\nsraSpanListOr(sraSpanList *dest, const sraSpanList *src) {\r\n  sraSpan *d_curr, *s_curr;\r\n  int s_start, s_end;\r\n\r\n  if (!dest) {\r\n    if (!src) {\r\n      return;\r\n    } else {\r\n      rfbErr(\"sraSpanListOr:incompatible spans (only one NULL!)\\n\");\r\n      return;\r\n    }\r\n  }\r\n\r\n  d_curr = dest->front._next;\r\n  s_curr = src->front._next;\r\n  s_start = s_curr->start;\r\n  s_end = s_curr->end;\r\n  while (s_curr != &(src->back)) {\r\n\r\n    /* - If we are at end of destination list OR\r\n       If the new span comes before the next destination one */\r\n    if ((d_curr == &(dest->back)) ||\r\n\t\t(d_curr->start >= s_end)) {\r\n      /* - Add the span */\r\n      sraSpanInsertBefore(sraSpanCreate(s_start, s_end,\r\n\t\t\t\t\ts_curr->subspan),\r\n\t\t\t  d_curr);\r\n      if (d_curr != &(dest->back))\r\n\tsraSpanMergePrevious(d_curr);\r\n      s_curr = s_curr->_next;\r\n      s_start = s_curr->start;\r\n      s_end = s_curr->end;\r\n    } else {\r\n\r\n      /* - If the new span overlaps the existing one */\r\n      if ((s_start < d_curr->end) &&\r\n\t  (s_end > d_curr->start)) {\r\n\r\n\t/* - Insert new span before the exi\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
