        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 2004 Martin Scharpf. All Rights Reserved.\r\n//\r\n\r\n\r\n#include <windows.h>\r\n#include <stdio.h>\r\n#include <lmcons.h>\r\n#include <stdlib.h>\r\n#include <wchar.h>\r\n#include <tchar.h>\r\n#include <lm.h>\r\n#include <stdio.h>\r\n#define SECURITY_WIN32\r\n#include <security.h>\r\n#include <sspi.h>\r\n#ifndef SEC_I_COMPLETE_NEEDED\r\n#include <issperr.h>\r\n#include <time.h>\r\n#endif\r\n#include <aclapi.h>\r\n#pragma hdrstop\r\n\r\n#define MAXLEN 256\r\n#define MAX_PREFERRED_LENGTH    ((DWORD) -1)\r\n#define BUFSIZE 1024\r\n\r\ntypedef DWORD (__stdcall *NetApiBufferFree_t)( void *buf );\r\n\r\ntypedef DWORD (__stdcall *NetWkstaGetInfoNT_t)( wchar_t *server, DWORD level, byte **buf );\r\ntypedef DWORD (__stdcall *NetWkstaGetInfo95_t)( char *domain,DWORD level, byte **buf );\r\n\r\n#include \"Auth_Seq.h\"\r\n\r\nBOOL GenClientContext(PAUTH_SEQ pAS, \r\n\t\t\t\t\t  PSEC_WINNT_AUTH_IDENTITY pAuthIdentity,\r\n\t\t\t\t\t  PVOID pIn, \r\n\t\t\t\t\t  DWORD cbIn, \r\n\t\t\t\t\t  PVOID pOut, \r\n\t\t\t\t\t  PDWORD pcbOut, \r\n\t\t\t\t\t  PBOOL pfDone);\r\n\r\nBOOL GenServerContext(PAUTH_SEQ pAS, \r\n\t\t\t\t\t  PVOID pIn, \r\n\t\t\t\t\t  DWORD cbIn, \r\n\t\t\t\t\t  PVOID pOut,\r\n\t\t\t\t\t  PDWORD pcbOut, \r\n\t\t\t\t\t  PBOOL pfDone);\r\n\r\nvoid UnloadSecurityDll(HMODULE hModule);\r\n\r\nHMODULE LoadSecurityDll();\r\n",
