        "file": "3rdparty/ultravnc/rdr/xzOutStream.h",
        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 2002 RealVNC Ltd. All Rights Reserved.\r\n//\r\n\r\n\r\n//\r\n// xzOutStream streams to a compressed data stream (underlying), compressing\r\n// with zlib on the fly.\r\n//\r\n#ifdef _XZ\r\n#ifndef __RDR_xzOutStream_H__\r\n#define __RDR_xzOutStream_H__\r\n\r\n#include \"OutStream.h\"\r\n\r\n#define LZMA_API_STATIC\r\n#ifndef _VS2008\r\n#include <stdint.h>\r\n#endif\r\n#ifdef _XZ\r\n#ifdef _VCPKG\r\n#include  <lzma.h>\r\n#else\r\n#include \"../xz/src/liblzma/api/lzma.h\"\r\n#endif\r\n#endif\r\n\r\nnamespace rdr {\r\n\r\n  class xzOutStream : public OutStream {\r\n\r\n  public:\r\n\r\n    // adzm - 2010-07 - Custom compression level\r\n    xzOutStream(OutStream* os=0, int bufSize=0);\r\n    virtual ~xzOutStream();\r\n\r\n\tvoid SetCompressLevel(int compression);\r\n\r\n    void setUnderlying(OutStream* os);\r\n    void flush();\r\n    int length();\r\n\r\n  private:\r\n\r\n    void ensure_stream_codec();\r\n\r\n    int overrun(int itemSize, int nItems);\r\n\r\n    OutStream* underlying;\r\n    int bufSize;\r\n    int offset;\r\n#ifdef _XZ\r\n\tlzma_stream* ls;\r\n\tlzma_options_lzma ls_options;\r\n#endif\r\n    U8* start;\r\n  };\r\n\r\n} // end of namespace rdr\r\n\r\n#endif\r\n#endif\r\n",
        "implementation": [
          "path: 3rdparty/ultravnc/rdr/xzOutStream.h",
          "GitHub: https://github.com/CanonEngineer/CustomizeVeyonProject/blob/main/3rdparty/ultravnc/rdr/xzOutStream.h"
        ]
