        "file": "3rdparty/ultravnc/rdr/ZstdInStream.h",
        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 2002 RealVNC Ltd. All Rights Reserved.\r\n//\r\n\r\n\r\n//\r\n// ZstdInStream streams from a compressed data stream (\"underlying\"),\r\n// decompressing with zlib or zstd on the fly.\r\n//\r\n#ifndef __RDR_ZSTDINSTREAM_H__\r\n#define __RDR_ZSTDINSTREAM_H__\r\n\r\n#pragma once\r\n\r\n#include \"InStream.h\"\r\n#ifdef _VCPKG\r\n#include <zstd.h>\r\n#else\r\n#include \"../zstd/lib/zstd.h\"\r\n#endif\r\n\r\nstruct z_stream_s;\r\n\r\nnamespace rdr {\r\n\r\n  class ZstdInStream : public InStream {\r\n\r\n  public:\r\n\r\n    ZstdInStream(int bufSize=0);\r\n    virtual ~ZstdInStream();\r\n\r\n    void setUnderlying(InStream* is, int bytesIn);\r\n    void reset();\r\n    int pos();\r\n\r\n  private:\r\n\r\n    int overrun(int itemSize, int nItems);\r\n    void decompress();\r\n\r\n    InStream* underlying;\r\n    int bufSize;\r\n    int offset;\r\n    int bytesIn;\r\n    U8* start;\r\n\r\n\tZSTD_outBuffer* outBuffer;\r\n\tZSTD_inBuffer* inBuffer;\r\n\tZSTD_DStream* zstds;\r\n\r\n  };\r\n} // end of namespace rdr\r\n\r\n#endif\r\n",
