        "file": "3rdparty/ultravnc/winvnc/winvnc/DlgChangePassword.h",
        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n//\r\n\r\n\r\n#pragma once\r\n#include \"stdhdrs.h\"\r\n\r\nclass DlgChangePassword\r\n{\r\nprivate:\r\n\tHWND DlgChangePasswordHwnd = NULL;\r\n\tchar title[1024]{};\r\n\tint passwordSize;\r\n\tchar passwd[1024];\r\npublic:\r\n\tDlgChangePassword();\r\n\tint ShowDlg(HWND parentWindow, char* title, int passwordSize);\r\n\t~DlgChangePassword();\r\n\tbool InitDialog(HWND hwnd);\r\n\tvoid onOK(HWND hwnd);\r\n\tchar* getPassword();\r\n};\r\n\r\n",
