        "file": "3rdparty/ultravnc/winvnc/winvnc/stdhdrs.h",
        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 2002 RealVNC Ltd. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999 AT&T Laboratories Cambridge. All Rights Reserved.\r\n//\r\n\r\n\r\n//need to be added for VS 2005\r\n\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n#define _Gii\r\n#endif\r\n#ifdef _Gii\r\n#ifndef WINVER                  // Specifies that the minimum required platform is Windows 7.\r\n#define WINVER 0x0602           // Change this to the appropriate value to target other versions of Windows.\r\n#endif\r\n\r\n#ifndef _WIN32_WINNT            // Specifies that the minimum required platform is Windows 7.\r\n#define _WIN32_WINNT 0x0602     // Change this to the appropriate value to target other versions of Windows.\r\n#endif     \r\n\r\n//#ifndef _WIN32_WINDOWS          // Specifies that the minimum required platform is Windows 98.\r\n//#define _WIN32_WINDOWS 0x0410 // Change this to the appropriate value to target Windows Me or later.\r\n//#endif\r\n\r\n#ifndef _WIN32_IE                       // Specifies that the minimum required platform is Internet Explorer 7.0.\r\n#define _WIN32_IE 0x0600        // Change this to the appropriate value to target other versions of IE.\r\n#endif\r\n#endif\r\n\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n#ifndef _HAS_STD_BYTE\r\n#define _HAS_STD_BYTE 0\r\n#endif\r\n#endif\r\n\r\n/*#ifdef _USE_DESKTOPDUPLICATION\r\n#define _WIN32_WINNT 0x0602\r\n#ifndef WINVER\r\n#define WINVER 0x0602\r\n#endif\r\n#else\r\n#define _WIN32_WINDOWS 0x0510\r\n#ifndef WINVER\r\n#define WINVER 0x0500\r\n#endif\r\n#endif*/\r\n\r\n#define WIN32_LEAN_AND_MEAN\r\n#ifndef STRICT\r\n#define STRICT\r\n#endif\r\n\r\n//compile special case, rfb port is used for java and rfb\r\n#include <ws2tcpip.h>\r\n#include <winsock2.h>\r\n#include <windows.h>\r\n#include <shellapi.h>\r\n//#include <winsock2.h>\r\n\r\n#include <malloc.h>\r\n#include <stdio.h>\r\n#include <process.h>\r\n#include <crtdbg.h>\r\n#include \"HelperFunctions.h\"\r\n\r\n#ifdef ULTRAVNC_VEYON_SUPPORT\r\n#include <QString>\r\n#endif\r\n\r\n//#include \"dpi.h\"\r\n\r\n// LOGGING SUPPORT\r\nvoid *memcpy_amd(void *dest, const void *src, size_t n);\r\nbool CheckVideoDriver(bool);\r\n#define MAXPATH 256\r\n\r\n#include \"vnclog.h\"\r\nextern VNCLog vnclog;\r\n\r\n#ifdef ULTRAVNC_VEYON_SUPPORT\r\n#define LL_NONE\t\t0\r\n#define LL_STATE\t1\r\n#define LL_CLIENTS\t2\r\n#define LL_CONNERR\t3\r\n#define LL_SOCKERR\t4\r\n#define LL_INTERR\t5\r\n#define LL_ERROR\t6\r\n#define LL_LOGSCREEN -1\r\n#else\r\n// No logging at all\r\n#define LL_NONE\t\t0\r\n// Log server startup/shutdown\r\n#define LL_STATE\t0\r\n// Log connect/disconnect\r\n#define LL_CLIENTS\t1\r\n// Show on Logscreen\r\n#define LL_LOGSCREEN -1\r\n// Log connection errors (wrong pixfmt, etc)\r\n#define LL_CONNERR\t0\r\n// Log socket errors\r\n#define LL_SOCKERR\t4\r\n// Log internal errors\r\n#define LL_INTERR\t0\r\n#endif\r\n\r\n// Log internal warnings\r\n#define LL_INTWARN\t8\r\n// Log internal info\r\n#define LL_INTINFO\t9\r\n// Log socket errors\r\n#define LL_SOCKINFO\t10\r\n// Log everything, including internal table setup, etc.\r\n#define LL_ALL\t\t10\r\n\r\n// Macros for sticking in the current file name\r\n#ifdef ULTRAVNC_VEYON_SUPPORT\r\n#define VNCLOG(s)\t(QStringLiteral(\"%1: %2\").arg(QLatin1String(__PRETTY_FUNCTION__)).arg(QStringLiteral(s)).toUtf8().constData())\r\n#else\r\n#define VNCLOG(s)\t(__FUNCTION__ \" : \" s)\r\n#endif\r\n//#if MSC_VER > 12\r\n#ifndef _X64\r\n#pragma comment(linker,\"/manifestdependency:\\\"type='Win32' name='Microsoft.Windows.Common-Controls' version='6.0.0.0' processorArchitecture='X86' publicKeyToken='6595b64144ccf1df' language='*'\\\"\")\r\n#else\r\n#pragma comment(linker,\"/manifestdependency:\\\"type='Win32' name='Microsoft.Windows.Common-Controls' version='6.0.0.0' processorArchitecture='amd64' publicKeyToken='6595b64144ccf1df' language='*'\\\"\")\r\n#endif\r\n//#endif\r\n//#define memcpy memcpy_amd\r\n//remove comment to compiler for >=athlon  or >=PIII\r\n\r\nextern void WriteLog(char* sender, char *format, ...);\r\n#ifdef _DEBUG\r\n#define OutputDevMessage(...) WriteLog(__FUNCTION__, __VA_ARGS__);\r\n#else\r\n#define OutputDevMessage(...)\r\n#endif\r\n\r\n#ifdef HIGH_PRECISION\r\n#define GetTimeFunction timeGetTime\r\n#pragma comment(lib, \"winmm.lib\")\r\n#else\r\n#define GetTimeFunction GetTickCount\r\n#endif\r\n",
