        "file": "3rdparty/ultravnc/winvnc/winvnc/vncabout.h",
        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999 AT&T Laboratories Cambridge. All Rights Reserved.\r\n//\r\n\r\n\r\n// vncAbout\r\n\r\n// Object implementing the About dialog for UltraVNC Server.\r\n\r\nclass vncAbout;\r\n\r\n#if (!defined(_WINVNC_VNCABOUT))\r\n#define _WINVNC_VNCABOUT\r\n\r\n// Includes\r\n#include \"stdhdrs.h\"\r\n\r\n// The vncAbout class itself\r\nclass vncAbout\r\n{\r\npublic:\r\n\t// Constructor/destructor\r\n\tvncAbout();\r\n\t~vncAbout();\r\n\r\n\t// Initialisation\r\n\tBOOL Init();\r\n\r\n\t// The dialog box window proc\r\n\tstatic BOOL CALLBACK DialogProc(HWND hwnd, UINT uMsg, WPARAM wParam, LPARAM lParam);\r\n\r\n\t// General\r\n\tvoid Show(BOOL show);\r\n\r\n\t// Implementation\r\n\tBOOL m_dlgvisible;\r\n};\r\n\r\n#endif // _WINVNC_VNCABOUT\r\n",
