        "code": "// This file is part of UltraVNC\r\n// https://github.com/ultravnc/UltraVNC\r\n// https://uvnc.com/\r\n//\r\n// SPDX-License-Identifier: GPL-3.0-or-later\r\n//\r\n// SPDX-FileCopyrightText: Copyright (C) 2002-2025 UltraVNC Team Members. All Rights Reserved.\r\n// SPDX-FileCopyrightText: Copyright (C) 1999-2002 Vdacc-VNC & eSVNC Projects. All Rights Reserved.\r\n//\r\n\r\n\r\n#if !defined(DISPL)\r\n#define DISPL\r\ntypedef HRESULT (CALLBACK *P_DwmIsCompositionEnabled) (BOOL *pfEnabled); \r\ntypedef HRESULT (CALLBACK *P_DwmEnableComposition) (BOOL   fEnable); \r\n\r\nclass VNC_OSVersion\r\n{\r\npublic:\r\n\tstatic VNC_OSVersion* getInstance() {\r\n\r\n\t\treturn (!vnc_OSVersion) ?\r\n\t\t\tvnc_OSVersion = new VNC_OSVersion :\r\n\t\t\tvnc_OSVersion;\r\n\t}\r\n\tstatic void releaseInstance() {\r\n\t\tif (vnc_OSVersion)\r\n\t\t\tdelete vnc_OSVersion;\r\n\t}\r\n\r\n\tVNC_OSVersion();\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n\tvirtual ~VNC_OSVersion();\r\n\tvoid SetAeroState();\r\n#endif\r\n\tbool CaptureAlphaBlending();\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n\tvoid DisableAero(VOID);\r\n\tvoid ResetAero(VOID);\r\n#endif\r\n\tbool OS_WIN10;\r\n\tbool OS_WIN10_TRANS;\r\n\tbool OS_WIN8;\r\n\tbool OS_WIN7;\r\n\tbool OS_VISTA;\r\n\tbool OS_XP;\r\n\tbool OS_W2K;\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n\tbool OS_AERO_ON;\r\n\tbool OS_LAYER_ON;\r\n#endif\r\n\tbool OS_NOTSUPPORTED;\r\n\tbool OS_BEFOREVISTA;\r\n\tbool OS_MINIMUMVISTA;\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n\tbool AeroWasEnabled;\r\n\tbool isWINPE(VOID);\r\n\tvoid removeAlpha();\r\n\tbool OS_WINPE;\r\n#endif\r\nprotected:\t\r\n#ifndef ULTRAVNC_VEYON_SUPPORT\r\n\tHMODULE DMdll; \r\n\tvoid UnloadDM(VOID);\r\n\tbool LoadDM(VOID);\r\n\tP_DwmIsCompositionEnabled pfnDwmIsCompositionEnabled;\r\n\tP_DwmEnableComposition pfnDwmEnableComposition; \r\n#endif\r\n\tstatic VNC_OSVersion* vnc_OSVersion;\r\n};\r\n#endif",
