        "file": "3rdparty/x11vnc/src/nox11.h",
        "code": "#undef  HAVE_XSHM\r\n#define HAVE_XSHM 0\r\n#undef  HAVE_XTEST\r\n#define HAVE_XTEST 0\r\n#undef  HAVE_XTESTGRABCONTROL\r\n#define HAVE_XTESTGRABCONTROL 0\r\n#undef  HAVE_XKEYBOARD\r\n#define HAVE_XKEYBOARD 0\r\n#undef  HAVE_LIBXINERAMA\r\n#define HAVE_LIBXINERAMA 0\r\n#undef  HAVE_LIBXRANDR\r\n#define HAVE_LIBXRANDR 0\r\n#undef  HAVE_LIBXFIXES\r\n#define HAVE_LIBXFIXES 0\r\n#undef  HAVE_LIBXDAMAGE\r\n#define HAVE_LIBXDAMAGE 0\r\n#undef  HAVE_RECORD\r\n#define HAVE_RECORD 0\r\n#undef  HAVE_LIBXTRAP\r\n#define HAVE_LIBXTRAP 0\r\n#undef  HAVE_SOLARIS_XREADSCREEN\r\n#define HAVE_SOLARIS_XREADSCREEN 0\r\n#undef  HAVE_IRIX_XREADDISPLAY\r\n#define HAVE_IRIX_XREADDISPLAY 0\r\n#undef  HAVE_FBPM\r\n#define HAVE_FBPM 0\r\n\r\n/* default keysyms */\r\n#if 0\r\n/* XXX go with the subset in rfb/keysym.h for now */\r\n#define XK_MISCELLANY\r\n#define XK_XKB_KEYS\r\n#define XK_LATIN1\r\n#define XK_LATIN2\r\n#define XK_LATIN3\r\n#define XK_LATIN4\r\n#define XK_LATIN8\r\n#define XK_LATIN9\r\n#define XK_CAUCASUS\r\n#define XK_GREEK\r\n#define XK_KATAKANA\r\n#define XK_ARABIC\r\n#define XK_CYRILLIC\r\n#define XK_HEBREW\r\n#define XK_THAI\r\n#define XK_KOREAN\r\n#define XK_ARMENIAN\r\n#define XK_GEORGIAN\r\n#define XK_VIETNAMESE\r\n#define XK_CURRENCY\r\n#endif\r\n\r\n/*\r\n *\t$Xorg: X.h,v 1.4 2001/02/09 02:03:22 xorgcvs Exp $\r\n */\r\n\r\n/* Definitions for the X window system likely to be used by applications */\r\n\r\n#ifndef X_H\r\n#define X_H\r\n\r\n/***********************************************************\r\n\r\nCopyright 1987, 1998  The Open Group\r\n\r\nPermission to use, copy, modify, distribute, and sell this software and its\r\ndocumentation for any purpose is hereby granted without fee, provided that\r\nthe above copyright notice appear in all copies and that both that\r\ncopyright notice and this permission notice appear in supporting\r\ndocumentation.\r\n\r\nThe above copyright notice and this permission notice shall be included in\r\nall copies or substantial portions of the Software.\r\n\r\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\r\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\r\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT.  IN NO EVENT SHALL THE\r\nOPEN GROUP BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN\r\nAN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN\r\nCONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\r\n\r\nExcept as contained in this notice, the name of The Open Group shall not be\r\nused in advertising or otherwise to promote the sale, use or other dealings\r\nin this Software without prior written authorization from The Open Group.\r\n\r\n\r\nCopyright 1987 by Digital Equipment Corporation, Maynard, Massachusetts.\r\n\r\n                        All Rights Reserved\r\n\r\nPermission to use, copy, modify, and distribute this software and its \r\ndocumentation for any purpose and without fee is hereby granted, \r\nprovided that the above copyright notice appear in all copies and that\r\nboth that copyright notice and this permission notice appear in \r\nsupporting documentation, and that the name of Digital not be\r\nused in advertising or publicity pertaining to distribution of the\r\nsoftware without specific, written prior permission.  \r\n\r\nDIGITAL DISCLAIMS ALL WARRANTIES WITH REGARD TO THIS SOFTWARE, INCLUDING\r\nALL IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS, IN NO EVENT SHALL\r\nDIGITAL BE LIABLE FOR ANY SPECIAL, INDIRECT OR CONSEQUENTIAL DAMAGES OR\r\nANY DAMAGES WHATSOEVER RESULTING FROM LOSS OF USE, DATA OR PROFITS,\r\nWHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER TORTIOUS ACTION,\r\nARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF THIS\r\nSOFTWARE.\r\n\r\n******************************************************************/\r\n/* $XFree86: xc/include/X.h,v 1.5 2001/12/14 19:53:25 dawes Exp $ */\r\n\r\n#define X_PROTOCOL\t11\t\t/* current protocol version */\r\n#define X_PROTOCOL_REVISION 0\t\t/* current minor version */\r\n\r\n/* Resources */\r\n\r\n/*\r\n * _XSERVER64 must ONLY be defined when compiling X server sources on\r\n * systems where unsigned long is not 32 bits, must NOT be used in\r\n * client or library code.\r\n */\r\n#ifndef _XSERVER64\r\n#  ifndef _XTYPEDEF_XID\r\n#    define _XTYPEDEF_XID\r\ntypedef unsigned long XID;\r\n#  endif\r\n#  ifndef _XTYPEDEF_MASK\r\n#    define _XTYPEDEF_MASK\r\ntypedef unsigned long Mask;\r\n#  endif\r\n#  ifndef _XTYPEDEF_ATOM\r\n#    define _XTYPEDEF_ATOM\r\ntypedef unsigned long Atom;\t\t/* Also in Xdefs.h */\r\n#  endif\r\ntypedef unsigned long VisualID;\r\ntypedef unsigned long Time;\r\n#else\r\n#  include <X11/Xmd.h>\r\n#  ifndef _XTYPEDEF_XID\r\n#    define _XTYPEDEF_XID\r\ntypedef CARD32 XID;\r\n#  endif\r\n#  ifndef _XTYPEDEF_MASK\r\n#    define _XTYPEDEF_MASK\r\ntypedef CARD32 Mask;\r\n#  endif\r\n#  ifndef _XTYPEDEF_ATOM\r\n#    define _XTYPEDEF_ATOM\r\ntypedef CARD32 Atom;\r\n#  endif\r\ntypedef CARD32 VisualID;\r\ntypedef CARD32 Time;\r\n#endif\r\n\r\ntypedef XID Window;\r\ntypedef XID Drawable;\r\n#ifndef _XTYPEDEF_FONT\r\n#  define _XTYPEDEF_FONT\r\ntypedef XID Font;\r\n#endif\r\ntypedef XID Pixmap;\r\ntypedef XID Cursor;\r\ntypedef XID Colormap;\r\ntypedef XID GContext;\r\ntypedef XID KeySym;\r\n\r\ntypedef unsigned char KeyCode;\r\n\r\n/*****************************************************************\r\n * RESERVED RESOURCE AND CONSTANT DEFINITIONS\r\n *****************************************************************/\r\n\r\n#ifndef None\r\n#define None                 0L\t/* universal null resource or null atom */\r\n#endif\r\n\r\n#define ParentRelative       1L\t/* background pixmap in CreateWindow\r\n\t\t\t\t    and ChangeWindowAttributes */\r\n\r\n#define CopyFromParent       0L\t/* border pixmap in CreateWindow\r\n\t\t\t\t       and ChangeWindowAttributes\r\n\t\t\t\t   special VisualID and special window\r\n\t\t\t\t       class passed to CreateWindow */\r\n\r\n#define PointerWindow        0L\t/* destination window in SendEvent */\r\n#define InputFocus           1L\t/* destination window in SendEvent */\r\n\r\n#define PointerRoot          1L\t/* focus window in SetInputFocus */\r\n\r\n#define AnyPropertyType      0L\t/* special Atom, passed to GetProperty */\r\n\r\n#define AnyKey\t\t     0L\t/* special Key Code, passed to GrabKey */\r\n\r\n#define AnyButton            0L\t/* special Button Code, passed to GrabButton */\r\n\r\n#define AllTemporary         0L\t/* special Resource ID passed to KillClient */\r\n\r\n#define CurrentTime          0L\t/* special Time */\r\n\r\n#define NoSymbol\t     0L\t/* special KeySym */\r\n\r\n/***************************************************************** \r\n * EVENT DEFINITIONS \r\n *****************************************************************/\r\n\r\n/* Input Event Masks. Used as event-mask window attribute and as arguments\r\n   to Grab requests.  Not to be confused with event names.  */\r\n\r\n#define NoEventMask\t\t\t0L\r\n#define KeyPressMask\t\t\t(1L<<0)  \r\n#define KeyReleaseMask\t\t\t(1L<<1)  \r\n#define ButtonPressMask\t\t\t(1L<<2)  \r\n#define ButtonReleaseMask\t\t(1L<<3)  \r\n#define EnterWindowMask\t\t\t(1L<<4)  \r\n#define LeaveWindowMask\t\t\t(1L<<5)  \r\n#define PointerMotionMask\t\t(1L<<6)  \r\n#define PointerMotionHintMask\t\t(1L<<7)  \r\n#define Button1MotionMask\t\t(1L<<8)  \r\n#define Button2MotionMask\t\t(1L<<9)  \r\n#define Button3MotionMask\t\t(1L<<1\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
