        "code": "/*\r\n * CimedDialogStyle.h - shared CIMED dialog chrome for Veyon custom UI\r\n */\r\n\r\n#pragma once\r\n\r\n#include \"VeyonCore.h\"\r\n\r\n#include <QIcon>\r\n#include <QPixmap>\r\n#include <QWidget>\r\n\r\nclass QDialog;\r\nclass QFrame;\r\nclass QHBoxLayout;\r\nclass QLabel;\r\nclass QLineEdit;\r\nclass QPushButton;\r\nclass QVBoxLayout;\r\n\r\nclass VEYON_CORE_EXPORT CimedDialogStyle\r\n{\r\npublic:\r\n\tenum class HeaderIcon\r\n\t{\r\n\t\tNone,\r\n\t\tLogon,\r\n\t\tRemoteAccess\r\n\t};\r\n\r\n\tenum class InputIcon\r\n\t{\r\n\t\tUser,\r\n\t\tPassword,\r\n\t\tNetwork\r\n\t};\r\n\r\n\tstatic constexpr int StandardDialogWidth = 560;\r\n\tstatic constexpr int StandardDialogHeight = 420;\r\n\tstatic constexpr int TallDialogHeight = 500;\r\n\tstatic constexpr int VersionAlertDialogWidth = 680;\r\n\tstatic constexpr int VersionAlertDialogHeight = 600;\r\n\r\n\tstatic QString dialogStyleSheet();\r\n\tstatic QString headerStyleSheet();\r\n\tstatic QString contentPanelStyleSheet();\r\n\tstatic QString inputFrameStyleSheet();\r\n\tstatic QString inputEditStyleSheet();\r\n\tstatic QString primaryButtonStyleSheet();\r\n\tstatic QString accentButtonStyleSheet();\r\n\tstatic QString secondaryButtonStyleSheet();\r\n\tstatic QString denyButtonStyleSheet();\r\n\tstatic QString captionLabelStyleSheet();\r\n\tstatic QString descriptionLabelStyleSheet();\r\n\tstatic QString headerTitleStyleSheet();\r\n\tstatic QString versionLabelStyleSheet();\r\n\tstatic QString footerStyleSheet();\r\n\tstatic QString footerTextStyleSheet();\r\n\r\n\tstatic QIcon standardWindowIcon();\r\n\tstatic QPixmap drawHeaderIcon( HeaderIcon icon, int size = 22 );\r\n\tstatic QPixmap drawInputIcon( InputIcon icon, int size = 18 );\r\n\tstatic QPixmap drawDesktopAccessHeroIcon( int size = 64 );\r\n\tstatic QPixmap drawButtonIcon( const QString& kind, int size = 16 );\r\n\tstatic QPixmap logoWithTransparentBackground( const QString& resourcePath, int maxWidth );\r\n\r\n\tstatic QPushButton* createPrimaryButton( QWidget* parent, const QString& text, const QPixmap& icon = {} );\r\n\r\n\tstatic QWidget* createHeader( QWidget* parent, const QString& title, HeaderIcon icon = HeaderIcon::None );\r\n\tstatic QWidget* createBrandPanel( QWidget* parent );\r\n\tstatic QWidget* createFooter( QWidget* parent );\r\n\tstatic QFrame* createVerticalSeparator( QWidget* parent );\r\n\tstatic QFrame* createInputFrame( QWidget* parent );\r\n\tstatic QLineEdit* createInputEdit( QFrame* frame, const QString& placeholder );\r\n\tstatic QLineEdit* createInputWithIcon( QWidget* parent, InputIcon icon, const QString& placeholder );\r\n\r\n\tstatic QPushButton* createAccentButton( QWidget* parent, const QString& text, const QPixmap& icon = {} );\r\n\tstatic QPushButton* createSecondaryButton( QWidget* parent, const QString& text );\r\n\tstatic QPushButton* createDenyButton( QWidget* parent, const QString& text, const QPixmap& icon = {} );\r\n\r\n\tstatic void centerDialogOnScreen( QDialog* dialog, int width, int height );\r\n\r\n\tstatic void buildDialogShell( QDialog* dialog,\r\n\t\t\t\t\t\t\t\t  const QString& windowTitle,\r\n\t\t\t\t\t\t\t\t  int width,\r\n\t\t\t\t\t\t\t\t  int height,\r\n\t\t\t\t\t\t\t\t  HeaderIcon headerIcon,\r\n\t\t\t\t\t\t\t\t  QWidget*& headerWidget,\r\n\t\t\t\t\t\t\t\t  QWidget*& brandPanel,\r\n\t\t\t\t\t\t\t\t  QWidget*& contentPanel,\r\n\t\t\t\t\t\t\t\t  QVBoxLayout*& contentLayout,\r\n\t\t\t\t\t\t\t\t  QWidget*& footerWidget,\r\n\t\t\t\t\t\t\t\t  bool includeBrandPanel = true );\r\n\r\n};\r\n",
