        "file": "core/src/CimedHostInputDialog.cpp",
        "code": "/*\r\n * CimedHostInputDialog.cpp - CIMED styled manual remote access hostname dialog\r\n */\r\n\r\n#include \"CimedHostInputDialog.h\"\r\n\r\n#include \"CimedDialogStyle.h\"\r\n\r\n#include <QHBoxLayout>\r\n#include <QLabel>\r\n#include <QLineEdit>\r\n#include <QPushButton>\r\n\r\nQString CimedHostInputDialog::getHostAddress( QWidget* parent )\r\n{\r\n\tCimedHostInputDialog accessDialog( parent );\r\n\tif( accessDialog.exec() == QDialog::Accepted )\r\n\t{\r\n\t\treturn accessDialog.m_hostAddress;\r\n\t}\r\n\r\n\treturn {};\r\n}\r\n\r\nCimedHostInputDialog::CimedHostInputDialog( QWidget* parent ) :\r\n\tQDialog( parent )\r\n{\r\n\tconst auto windowTitle = tr( \"Remote access\" );\r\n\tsetWindowIcon( CimedDialogStyle::standardWindowIcon() );\r\n\r\n\tQWidget* headerWidget = nullptr;\r\n\tQWidget* brandPanel = nullptr;\r\n\tQWidget* contentPanel = nullptr;\r\n\tQVBoxLayout* contentLayout = nullptr;\r\n\tQWidget* footerWidget = nullptr;\r\n\r\n\tCimedDialogStyle::buildDialogShell( this,\r\n\t\t\t\t\t\t\t\t\t\twindowTitle,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::StandardDialogWidth,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::StandardDialogHeight,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::HeaderIcon::RemoteAccess,\r\n\t\t\t\t\t\t\t\t\t\theaderWidget,\r\n\t\t\t\t\t\t\t\t\t\tbrandPanel,\r\n\t\t\t\t\t\t\t\t\t\tcontentPanel,\r\n\t\t\t\t\t\t\t\t\t\tcontentLayout,\r\n\t\t\t\t\t\t\t\t\t\tfooterWidget );\r\n\r\n\tQ_UNUSED( headerWidget )\r\n\tQ_UNUSED( brandPanel )\r\n\tQ_UNUSED( footerWidget )\r\n\r\n\tauto* descriptionLabel = new QLabel(\r\n\t\ttr( \"No computer has been selected so you can enter a hostname \"\r\n\t\t\t\"or IP address of a computer for manual access:\" ),\r\n\t\tcontentPanel );\r\n\tdescriptionLabel->setWordWrap( true );\r\n\tdescriptionLabel->setStyleSheet( CimedDialogStyle::descriptionLabelStyleSheet() );\r\n\tcontentLayout->addWidget( descriptionLabel );\r\n\tcontentLayout->addSpacing( 4 );\r\n\r\n\tauto* hostCaption = new QLabel( tr( \"Hostname / IP\" ), contentPanel );\r\n\thostCaption->setStyleSheet( CimedDialogStyle::captionLabelStyleSheet() );\r\n\tcontentLayout->addWidget( hostCaption );\r\n\r\n\tm_hostEdit = CimedDialogStyle::createInputWithIcon( contentPanel,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::InputIcon::Network,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\ttr( \"Digite o hostname ou IP\" ) );\r\n\tcontentLayout->addWidget( qobject_cast<QFrame *>( m_hostEdit->parentWidget() ) );\r\n\r\n\tcontentLayout->addSpacing( 8 );\r\n\r\n\tauto* buttonsRow = new QHBoxLayout();\r\n\tbuttonsRow->setSpacing( 10 );\r\n\r\n\tauto* connectButton = CimedDialogStyle::createPrimaryButton(\r\n\t\tcontentPanel,\r\n\t\ttr( \"CONECTAR\" ),\r\n\t\tCimedDialogStyle::drawButtonIcon( QStringLiteral( \"connect\" ) ) );\r\n\tconnect( connectButton, &QPushButton::clicked, this, [this]() {\r\n\t\tm_hostAddress = m_hostEdit->text().trimmed();\r\n\t\taccept();\r\n\t} );\r\n\tbuttonsRow->addWidget( connectButton );\r\n\r\n\tauto* cancelButton = CimedDialogStyle::createSecondaryButton( contentPanel, tr( \"CANCELAR\" ) );\r\n\tconnect( cancelButton, &QPushButton::clicked, this, &QDialog::reject );\r\n\tbuttonsRow->addWidget( cancelButton );\r\n\tbuttonsRow->addStretch();\r\n\r\n\tcontentLayout->addLayout( buttonsRow );\r\n\tcontentLayout->addStretch();\r\n\r\n\tconnect( m_hostEdit, &QLineEdit::returnPressed, this, [this]() {\r\n\t\tm_hostAddress = m_hostEdit->text().trimmed();\r\n\t\taccept();\r\n\t} );\r\n\r\n\tm_hostEdit->setFocus();\r\n}\r\n",
