        "file": "core/src/CimedVersionAlertMonitor.h",
        "code": "/*\r\n\r\n * CimedVersionAlertMonitor.h - sentinel host monitor for incompatible Veyon alerts\r\n\r\n */\r\n\r\n\r\n\r\n#pragma once\r\n\r\n\r\n\r\n#include \"VeyonCore.h\"\r\n\r\n\r\n\r\n#include <QHash>\r\n\r\n#include <QObject>\r\n\r\n#include <QSet>\r\n\r\n#include <QTimer>\r\n\r\n\r\n\r\nclass FeatureWorkerManager;\r\n\r\n\r\n\r\nclass VEYON_CORE_EXPORT CimedVersionAlertMonitor : public QObject\r\n\r\n{\r\n\r\n\tQ_OBJECT\r\n\r\npublic:\r\n\r\n\tstatic void startOnSentinelHosts( FeatureWorkerManager& featureWorkerManager, QObject* parent );\r\n\r\n\r\n\r\nprivate:\r\n\r\n\tstruct AlertFileState\r\n\r\n\t{\r\n\r\n\t\tqint64 lastFileSize = 0;\r\n\r\n\t\tbool initialized = false;\r\n\r\n\t};\r\n\r\n\r\n\r\n\texplicit CimedVersionAlertMonitor( FeatureWorkerManager& featureWorkerManager, QObject* parent = nullptr );\r\n\r\n\r\n\r\n\tvoid pollAlertFiles();\r\n\r\n\tvoid pollAlertFile( const QString& alertPath );\r\n\r\n\r\n\r\n\tFeatureWorkerManager& m_featureWorkerManager;\r\n\r\n\tQTimer m_pollTimer;\r\n\r\n\tQHash<QString, AlertFileState> m_fileStates;\r\n\r\n\tQSet<QString> m_seenAlertFingerprints;\r\n\r\n\r\n\r\n};\r\n",
