        "file": "core/src/CimedVersionAlertPresenter.cpp",
        "code": "/*\r\r\n * CimedVersionAlertPresenter.cpp - routes version alert dialog to session worker\r\r\n */\r\r\n\r\r\n#include \"CimedVersionAlertPresenter.h\"\r\r\n\r\r\n#include \"BuiltinFeatures.h\"\r\r\n#include \"FeatureWorkerManager.h\"\r\r\n#include \"SystemTrayIcon.h\"\r\r\n#include \"VeyonCore.h\"\r\r\n\r\r\nCimedVersionAlertPresenter::CimedVersionAlertPresenter( QObject* parent ) :\r\r\n\tQObject( parent ),\r\r\n\tm_feature( Feature( QLatin1String( staticMetaObject.className() ),\r\r\n\t\t\t\t\t\tFeature::Flag::Service | Feature::Flag::Worker | Feature::Flag::Builtin,\r\r\n\t\t\t\t\t\tFeature::Uid( \"c8f4a2e1-5d6b-4a9c-8f2e-1b3d7c9e0a4f\" ),\r\r\n\t\t\t\t\t\tFeature::Uid(),\r\r\n\t\t\t\t\t\ttr( \"CIMED version alert\" ), {}, {} ) ),\r\r\n\tm_features( { m_feature } )\r\r\n{\r\r\n}\r\r\n\r\r\nvoid CimedVersionAlertPresenter::showAlert( FeatureWorkerManager& featureWorkerManager,\r\r\n\t\t\t\t\t\t\t\t\t\t\tconst QString& originIp,\r\r\n\t\t\t\t\t\t\t\t\t\t\tconst QString& originHost,\r\r\n\t\t\t\t\t\t\t\t\t\t\tconst QString& adUser,\r\r\n\t\t\t\t\t\t\t\t\t\t\tconst QString& adDisplayName,\r\r\n\t\t\t\t\t\t\t\t\t\t\tconst QString& detectedVersion )\r\r\n{\r\r\n\tVeyonCore::builtinFeatures().systemTrayIcon().showVersionAlert( featureWorkerManager,\r\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\toriginIp,\r\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\toriginHost,\r\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tadUser,\r\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tadDisplayName,\r\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\tdetectedVersion );\r\r\n}\r\r\n\r\r\nbool CimedVersionAlertPresenter::handleFeatureMessage( VeyonWorkerInterface& worker, const FeatureMessage& message )\r\r\n{\r\r\n\tQ_UNUSED( worker )\r\r\n\tQ_UNUSED( message )\r\r\n\treturn false;\r\r\n}\r\r\n\r",
