        "code": "/*\r\n * CimedVersionAlertPresenter.h - routes version alert dialog to session worker\r\n */\r\n\r\n#pragma once\r\n\r\n#include \"FeatureProviderInterface.h\"\r\n\r\nclass FeatureWorkerManager;\r\n\r\nclass VEYON_CORE_EXPORT CimedVersionAlertPresenter : public QObject, public FeatureProviderInterface, public PluginInterface\r\n{\r\n\tQ_OBJECT\r\n\tQ_INTERFACES(FeatureProviderInterface PluginInterface)\r\npublic:\r\n\tenum class Argument\r\n\t{\r\n\t\tOriginIp,\r\n\t\tOriginHost,\r\n\t\tAdUser,\r\n\t\tAdDisplayName,\r\n\t\tDetectedVersion\r\n\t};\r\n\tQ_ENUM(Argument)\r\n\r\n\texplicit CimedVersionAlertPresenter( QObject* parent = nullptr );\r\n\t~CimedVersionAlertPresenter() override = default;\r\n\r\n\tvoid showAlert( FeatureWorkerManager& featureWorkerManager,\r\n\t\t\t\t\tconst QString& originIp,\r\n\t\t\t\t\tconst QString& originHost,\r\n\t\t\t\t\tconst QString& adUser,\r\n\t\t\t\t\tconst QString& adDisplayName,\r\n\t\t\t\t\tconst QString& detectedVersion );\r\n\r\n\tPlugin::Uid uid() const override\r\n\t{\r\n\t\treturn Plugin::Uid{ QStringLiteral( \"a4c2e8f1-9b3d-4f6a-8c1e-2d7f5a9b0e31\" ) };\r\n\t}\r\n\r\n\tQVersionNumber version() const override\r\n\t{\r\n\t\treturn QVersionNumber( 1, 0 );\r\n\t}\r\n\r\n\tQString name() const override\r\n\t{\r\n\t\treturn QStringLiteral( \"CimedVersionAlertPresenter\" );\r\n\t}\r\n\r\n\tQString description() const override\r\n\t{\r\n\t\treturn tr( \"CIMED incompatible Veyon version alert\" );\r\n\t}\r\n\r\n\tQString vendor() const override\r\n\t{\r\n\t\treturn QStringLiteral( \"CIMED\" );\r\n\t}\r\n\r\n\tQString copyright() const override\r\n\t{\r\n\t\treturn QStringLiteral( \"CIMED\" );\r\n\t}\r\n\r\n\tconst FeatureList& featureList() const override\r\n\t{\r\n\t\treturn m_features;\r\n\t}\r\n\r\n\tbool controlFeature( Feature::Uid featureUid, Operation operation, const QVariantMap& arguments,\r\n\t\t\t\t\t\tconst ComputerControlInterfaceList& computerControlInterfaces ) override\r\n\t{\r\n\t\tQ_UNUSED( featureUid )\r\n\t\tQ_UNUSED( operation )\r\n\t\tQ_UNUSED( arguments )\r\n\t\tQ_UNUSED( computerControlInterfaces )\r\n\t\treturn false;\r\n\t}\r\n\r\n\tbool handleFeatureMessage( VeyonWorkerInterface& worker, const FeatureMessage& message ) override;\r\n\r\nprivate:\r\n\tenum class FeatureCommand\r\n\t{\r\n\t\tShowVersionAlert\r\n\t};\r\n\r\n\tconst Feature m_feature;\r\n\tconst FeatureList m_features;\r\n\r\n};\r\n",
