        "file": "core/src/CimedVersionAlertWriter.h",
        "code": "/*\r\n * CimedVersionAlertWriter.h - central alert file for incompatible Veyon builds\r\n */\r\n\r\n#pragma once\r\n\r\n#include <QString>\r\n#include <QStringList>\r\n\r\nclass CimedVersionAlertWriter\r\n{\r\npublic:\r\n\tstruct IncompatibleConnectionDetails\r\n\t{\r\n\t\tQString originIp;\r\n\t\tQString originHost;\r\n\t\tQString adUser;\r\n\t\tQString adDisplayName;\r\n\t\tQString detectedVersion;\r\n\t\tQString destinationHost;\r\n\t\tQString destinationIp;\r\n\t};\r\n\r\n\tstatic QStringList alertLogFilePaths();\r\n\tstatic bool recordInboundIncompatibleConnection( const IncompatibleConnectionDetails& details );\r\n\r\n};\r\n",
