        "file": "core/src/DesktopAccessConfirmDialog.cpp",
        "code": "/*\r\n * DesktopAccessConfirmDialog.cpp - CIMED styled desktop access confirmation dialog\r\n */\r\n\r\n#include \"DesktopAccessConfirmDialog.h\"\r\n\r\n#include \"CimedDialogStyle.h\"\r\n#include \"PlatformCoreFunctions.h\"\r\n#include \"VeyonCore.h\"\r\n\r\n#include <QGridLayout>\r\n#include <QIcon>\r\n#include <QLabel>\r\n#include <QPushButton>\r\n\r\nDesktopAccessDialog::Choice DesktopAccessConfirmDialog::exec( const QString& user,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t  const QString& host,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t  QWidget* parent )\r\n{\r\n\tDesktopAccessConfirmDialog accessDialog( user, host, parent );\r\n\tVeyonCore::platform().coreFunctions().raiseWindow( &accessDialog, true );\r\n\taccessDialog.QDialog::exec();\r\n\treturn accessDialog.m_choice;\r\n}\r\n\r\nDesktopAccessConfirmDialog::DesktopAccessConfirmDialog( const QString& user,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tconst QString& host,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\tQWidget* parent ) :\r\n\tQDialog( parent ),\r\n\tm_choice( DesktopAccessDialog::ChoiceNo )\r\n{\r\n\tconst auto windowTitle = tr( \"Confirm desktop access\" );\r\n\tsetWindowIcon( CimedDialogStyle::standardWindowIcon() );\r\n\r\n\tQWidget* headerWidget = nullptr;\r\n\tQWidget* brandPanel = nullptr;\r\n\tQWidget* contentPanel = nullptr;\r\n\tQVBoxLayout* contentLayout = nullptr;\r\n\tQWidget* footerWidget = nullptr;\r\n\r\n\tCimedDialogStyle::buildDialogShell( this,\r\n\t\t\t\t\t\t\t\t\t\twindowTitle,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::StandardDialogWidth,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::TallDialogHeight,\r\n\t\t\t\t\t\t\t\t\t\tCimedDialogStyle::HeaderIcon::None,\r\n\t\t\t\t\t\t\t\t\t\theaderWidget,\r\n\t\t\t\t\t\t\t\t\t\tbrandPanel,\r\n\t\t\t\t\t\t\t\t\t\tcontentPanel,\r\n\t\t\t\t\t\t\t\t\t\tcontentLayout,\r\n\t\t\t\t\t\t\t\t\t\tfooterWidget );\r\n\r\n\tQ_UNUSED( headerWidget )\r\n\tQ_UNUSED( brandPanel )\r\n\tQ_UNUSED( footerWidget )\r\n\tQ_UNUSED( user )\r\n\tQ_UNUSED( host )\r\n\r\n\tauto* heroIcon = new QLabel( contentPanel );\r\n\theroIcon->setAlignment( Qt::AlignHCenter );\r\n\theroIcon->setPixmap( CimedDialogStyle::drawDesktopAccessHeroIcon( 72 ) );\r\n\tcontentLayout->addWidget( heroIcon );\r\n\tcontentLayout->addSpacing( 4 );\r\n\r\n\tauto* messageLabel = new QLabel(\r\n\t\ttr( \"Um usuário deseja acessar sua área de trabalho. Deseja permitir?\" ),\r\n\t\tcontentPanel );\r\n\tmessageLabel->setWordWrap( true );\r\n\tmessageLabel->setAlignment( Qt::AlignHCenter );\r\n\tmessageLabel->setStyleSheet( QStringLiteral(\r\n\t\t\"font-size: 13px; font-weight: 600; color: #e2e8f0; line-height: 1.45;\" ) );\r\n\tcontentLayout->addWidget( messageLabel );\r\n\tcontentLayout->addSpacing( 12 );\r\n\r\n\tauto* buttonsGrid = new QGridLayout();\r\n\tbuttonsGrid->setHorizontalSpacing( 10 );\r\n\tbuttonsGrid->setVerticalSpacing( 10 );\r\n\r\n\tauto* yesButton = CimedDialogStyle::createPrimaryButton(\r\n\t\tcontentPanel,\r\n\t\ttr( \"SIM\" ),\r\n\t\tCimedDialogStyle::drawButtonIcon( QStringLiteral( \"check\" ) ) );\r\n\tauto* alwaysButton = CimedDialogStyle::createAccentButton(\r\n\t\tcontentPanel,\r\n\t\ttr( \"SEMPRE\" ),\r\n\t\tCimedDialogStyle::drawButtonIcon( QStringLiteral( \"star\" ) ) );\r\n\tauto* noButton = CimedDialogStyle::createDenyButton(\r\n\t\tcontentPanel,\r\n\t\ttr( \"NAO\" ),\r\n\t\tCimedDialogStyle::drawButtonIcon( QStringLiteral( \"deny\" ) ) );\r\n\tauto* neverButton = CimedDialogStyle::createSecondaryButton( contentPanel, tr( \"NUNCA\" ) );\r\n\tneverButton->setIcon( QIcon( CimedDialogStyle::drawButtonIcon( QStringLiteral( \"deny\" ) ) ) );\r\n\tneverButton->setIconSize( QSize( 16, 16 ) );\r\n\r\n\tfor( auto* button : { yesButton, alwaysButton, noButton, neverButton } )\r\n\t{\r\n\t\tbutton->setMinimumHeight( 48 );\r\n\t\tbutton->setMinimumWidth( 108 );\r\n\t}\r\n\r\n\tbuttonsGrid->addWidget( yesButton, 0, 0 );\r\n\tbuttonsGrid->addWidget( alwaysButton, 0, 1 );\r\n\tbuttonsGrid->addWidget( noButton, 1, 0 );\r\n\tbuttonsGrid->addWidget( neverButton, 1, 1 );\r\n\r\n\tcontentLayout->addLayout( buttonsGrid );\r\n\tcontentLayout->addStretch();\r\n\r\n\tconnect( yesButton, &QPushButton::clicked, this, [this]() {\r\n\t\tm_choice = DesktopAccessDialog::ChoiceYes;\r\n\t\taccept();\r\n\t} );\r\n\tconnect( alwaysButton, &QPushButton::clicked, this, [this]() {\r\n\t\tm_choice = DesktopAccessDialog::ChoiceAlways;\r\n\t\taccept();\r\n\t} );\r\n\tconnect( noButton, &QPushButton::clicked, this, [this]() {\r\n\t\tm_choice = DesktopAccessDialog::ChoiceNo;\r\n\t\treject();\r\n\t} );\r\n\tconnect( neverButton, &QPushButton::clicked, this, [this]() {\r\n\t\tm_choice = DesktopAccessDialog::ChoiceNever;\r\n\t\taccept();\r\n\t} );\r\n\r\n\tneverButton->setDefault( true );\r\n\tneverButton->setFocus();\r\n}\r\n\r\nvoid DesktopAccessConfirmDialog::reject()\r\n{\r\n\tm_choice = DesktopAccessDialog::ChoiceNo;\r\n\tQDialog::reject();\r\n}\r\n",
