        "code": "/*\r\n * TamperLogPasswordDialog.cpp - admin password prompt for protected tamper logs\r\n */\r\n\r\n#include <QDateTime>\r\n#include <QFrame>\r\n#include <QHBoxLayout>\r\n#include <QLabel>\r\n#include <QLineEdit>\r\n#include <QPainter>\r\n#include <QPainterPath>\r\n#include <QPixmap>\r\n#include <QPushButton>\r\n#include <QSignalBlocker>\r\n#include <QToolButton>\r\n#include <QVBoxLayout>\r\n\r\n#include \"TamperLogPasswordDialog.h\"\r\n#include \"TamperLogProtector.h\"\r\n\r\nnamespace\r\n{\r\n\r\nconstexpr int DialogWidth = 560;\r\nconstexpr int DialogHeight = 360;\r\n\r\nQPixmap drawShieldIcon( int size, const QColor& shieldColor, const QColor& lockColor, int lockScalePercent = 35 )\r\n{\r\n\tQPixmap pixmap( size, size );\r\n\tpixmap.fill( Qt::transparent );\r\n\r\n\tQPainter painter( &pixmap );\r\n\tpainter.setRenderHint( QPainter::Antialiasing, true );\r\n\r\n\tQPainterPath shieldPath;\r\n\tconst auto w = static_cast<qreal>( size );\r\n\tconst auto h = static_cast<qreal>( size );\r\n\tshieldPath.moveTo( w * 0.5, h * 0.06 );\r\n\tshieldPath.lineTo( w * 0.88, h * 0.22 );\r\n\tshieldPath.lineTo( w * 0.82, h * 0.72 );\r\n\tshieldPath.quadTo( w * 0.5, h * 0.96, w * 0.18, h * 0.72 );\r\n\tshieldPath.lineTo( w * 0.12, h * 0.22 );\r\n\tshieldPath.closeSubpath();\r\n\r\n\tpainter.setPen( Qt::NoPen );\r\n\tpainter.setBrush( shieldColor );\r\n\tpainter.drawPath( shieldPath );\r\n\r\n\tconst auto lockSize = size * lockScalePercent / 100;\r\n\tconst auto lockX = ( size - lockSize ) / 2;\r\n\tconst auto lockY = size * 0.38;\r\n\r\n\tpainter.setBrush( lockColor );\r\n\tpainter.drawRoundedRect( QRectF( lockX + lockSize * 0.22, lockY, lockSize * 0.56, lockSize * 0.52 ), 3, 3 );\r\n\tpainter.drawChord( QRectF( lockX, lockY - lockSize * 0.28, lockSize, lockSize * 0.62 ), 0, 180 * 16 );\r\n\r\n\treturn pixmap;\r\n}\r\n\r\nQPixmap drawEyeIcon( int size, const QColor& color )\r\n{\r\n\tQPixmap pixmap( size, size );\r\n\tpixmap.fill( Qt::transparent );\r\n\r\n\tQPainter painter( &pixmap );\r\n\tpainter.setRenderHint( QPainter::Antialiasing, true );\r\n\tpainter.setPen( QPen( color, 1.6 ) );\r\n\tpainter.setBrush( Qt::NoBrush );\r\n\tpainter.drawEllipse( QRectF( size * 0.12, size * 0.28, size * 0.76, size * 0.44 ) );\r\n\tpainter.setBrush( color );\r\n\tpainter.setPen( Qt::NoPen );\r\n\tpainter.drawEllipse( QRectF( size * 0.38, size * 0.40, size * 0.24, size * 0.24 ) );\r\n\r\n\treturn pixmap;\r\n}\r\n\r\nQLabel* createIconLabel( const QPixmap& pixmap, QWidget* parent )\r\n{\r\n\tauto* label = new QLabel( parent );\r\n\tlabel->setPixmap( pixmap );\r\n\tlabel->setAlignment( Qt::AlignCenter );\r\n\treturn label;\r\n}\r\n\r\nQFrame* createVerticalSeparator( QWidget* parent )\r\n{\r\n\tauto* line = new QFrame( parent );\r\n\tline->setFrameShape( QFrame::VLine );\r\n\tline->setFrameShadow( QFrame::Plain );\r\n\tline->setStyleSheet( QStringLiteral( \"color: #D1D5DB;\" ) );\r\n\treturn line;\r\n}\r\n\r\n}\r\n\r\nTamperLogPasswordDialog::TamperLogPasswordDialog( QWidget* parent ) :\r\n\tQDialog( parent )\r\n{\r\n\tsetWindowTitle( tr( \"Proteção de Log\" ) );\r\n\tsetWindowFlags( windowFlags() | Qt::WindowStaysOnTopHint );\r\n\tsetModal( true );\r\n\tsetFixedSize( DialogWidth, DialogHeight );\r\n\r\n\tsetStyleSheet( QStringLiteral(\r\n\t\t\"QDialog { background-color: #FFFFFF; }\"\r\n\t\t\"QLabel { color: #1F2937; }\" ) );\r\n\r\n\tauto* rootLayout = new QVBoxLayout( this );\r\n\trootLayout->setContentsMargins( 0, 0, 0, 0 );\r\n\trootLayout->setSpacing( 0 );\r\n\r\n\tauto* headerWidget = new QWidget( this );\r\n\theaderWidget->setStyleSheet( QStringLiteral(\r\n\t\t\"background-color: #FFFFFF; border-bottom: 1px solid #E5E7EB;\" ) );\r\n\tauto* headerLayout = new QHBoxLayout( headerWidget );\r\n\theaderLayout->setContentsMargins( 16, 12, 16, 12 );\r\n\theaderLayout->setSpacing( 10 );\r\n\r\n\tconst auto headerIcon = drawShieldIcon( 22, QColor( 37, 99, 235 ), QColor( 255, 255, 255 ), 40 );\r\n\theaderLayout->addWidget( createIconLabel( headerIcon, headerWidget ) );\r\n\r\n\tauto* headerTitle = new QLabel( tr( \"Proteção de Log\" ), headerWidget );\r\n\theaderTitle->setStyleSheet( QStringLiteral( \"font-size: 14px; font-weight: 600; color: #374151;\" ) );\r\n\theaderLayout->addWidget( headerTitle );\r\n\theaderLayout->addStretch();\r\n\trootLayout->addWidget( headerWidget );\r\n\r\n\tauto* bodyWidget = new QWidget( this );\r\n\tauto* bodyLayout = new QHBoxLayout( bodyWidget );\r\n\tbodyLayout->setContentsMargins( 24, 24, 24, 16 );\r\n\tbodyLayout->setSpacing( 24 );\r\n\r\n\tauto* brandPanel = new QWidget( bodyWidget );\r\n\tbrandPanel->setFixedWidth( 150 );\r\n\tauto* brandLayout = new QVBoxLayout( brandPanel );\r\n\tbrandLayout->setContentsMargins( 0, 8, 0, 0 );\r\n\tbrandLayout->setSpacing( 12 );\r\n\r\n\tconst auto brandIcon = drawShieldIcon( 88, QColor( 37, 99, 235 ), QColor( 255, 255, 255 ) );\r\n\tbrandLayout->addWidget( createIconLabel( brandIcon, brandPanel ), 0, Qt::AlignHCenter );\r\n\r\n\tauto* brandLabel = new QLabel( QStringLiteral( \"VEYON CIMED\" ), brandPanel );\r\n\tbrandLabel->setAlignment( Qt::AlignHCenter );\r\n\tbrandLabel->setStyleSheet( QStringLiteral(\r\n\t\t\"font-size: 18px; font-weight: 700; color: #1D4ED8; letter-spacing: 1px;\" ) );\r\n\tbrandLayout->addWidget( brandLabel );\r\n\tbrandLayout->addStretch();\r\n\r\n\tbodyLayout->addWidget( brandPanel );\r\n\tbodyLayout->addWidget( createVerticalSeparator( bodyWidget ) );\r\n\r\n\tm_contentPanel = new QWidget( bodyWidget );\r\n\tm_contentPanel->setObjectName( QStringLiteral( \"tamperLogContentPanel\" ) );\r\n\tauto* contentLayout = new QVBoxLayout( m_contentPanel );\r\n\tcontentLayout->setContentsMargins( 12, 12, 12, 12 );\r\n\tcontentLayout->setSpacing( 10 );\r\n\r\n\tauto* titleLabel = new QLabel( tr( \"Acesso Restrito\" ), m_contentPanel );\r\n\ttitleLabel->setStyleSheet( QStringLiteral( \"font-size: 20px; font-weight: 700; color: #2563EB;\" ) );\r\n\tcontentLayout->addWidget( titleLabel );\r\n\r\n\tauto* descriptionLabel = new QLabel(\r\n\t\ttr( \"Este arquivo contém registros de auditoria.\\nInforme sua senha para continuar.\" ),\r\n\t\tm_contentPanel );\r\n\tdescriptionLabel->setWordWrap( true );\r\n\tdescriptionLabel->setStyleSheet( QStringLiteral( \"font-size: 12px; color: #4B5563;\" ) );\r\n\tcontentLayout->addWidget( descriptionLabel );\r\n\r\n\tcontentLayout->addSpacing( 8 );\r\n\r\n\tauto* passwordCaption = new QLabel( tr( \"Senha\" ), m_contentPanel );\r\n\tpasswordCaption->setStyleSheet( QStringLiteral( \"font-size: 12px; font-weight: 600; color: #374151;\" ) );\r\n\tcontentLayout->addWidget( passwordCaption );\r\n\r\n\tm_passwordFrame = new QFrame( m_contentPanel );\r\n\tm_passwordFrame->setStyleSheet( QStringLiteral(\r\n\t\t\"QFrame { border: 1px solid #CBD5E1; border-radius: 6px; background: #FFFFFF; }\"\r\n\t\t\"QFrame:focus-within { border: 2px solid #2563EB; }\" ) );\r\n\tauto* passwordRow = new QHBoxLayout( m_passwordFrame );\r\n\tpasswordRow->setContentsMargins( 10, 4, 4, 4 );\r\n\tpasswordRow->setSpacing( 4 );\r\n\r\n\tm_passwordEdit = new QLineEdit( m_passwordFrame );\r\n\tm_passwordEdit->setEchoMode( QLineEdit::Password );\r\n\tm_passwordEdit->setMaxLength( 10 );\r\n\tm_passwordEdit->setPlaceholderText( tr( \"Digite a senha\" ) );\r\n\tm_passwordEdit->setFrame( false );\r\n\tm_passwordEdit->setStyleSheet( QStringLiteral(\r\n\t\t\"QLineEdit { border: none; background: transparent; font-size: 13px; color: #111827; }\" ) );\r\n\tpasswordRow->addWidget( m_passwordEdit, 1 );\r\n\r\n\tauto* toggleVisibilityButton = new QToolButton( m_passwordFrame \n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
