        "file": "core/src/TamperLogProtector.cpp",
        "code": "/*\r\n\r\n * TamperLogProtector.cpp - watches access logs and records tamper alerts\r\n\r\n */\r\n\r\n\r\n\r\n#include <QCoreApplication>\r\n\r\n#include <QCryptographicHash>\r\n\r\n#include <QDir>\r\n\r\n#include <QFile>\r\n\r\n#include <QFileInfo>\r\n\r\n#include <QTimer>\r\n#include <QThread>\r\n\r\n\r\n\r\n#include \"VeyonCore.h\"\r\n\r\n#include \"AccessLogWriter.h\"\r\n\r\n#include \"BuiltinFeatures.h\"\r\n\r\n#include \"FeatureWorkerManager.h\"\r\n\r\n#include \"Logger.h\"\r\n#include \"SystemTrayIcon.h\"\r\n#include \"TamperLogProtector.h\"\r\n\r\n\r\n\r\nnamespace\r\n\r\n{\r\n\r\n\r\n\r\nconstexpr auto AdminPasswordHash = \"8ab2cdcbd95fabaab0ef54a74c84a08b3e8c95c511f50c4992e9a8cac3c63863\";\r\n\r\n\r\n\r\nQString passwordSha256Hex( const QString& password )\r\n\r\n{\r\n\r\n\treturn QString::fromLatin1(\r\n\r\n\t\tQCryptographicHash::hash( password.toUtf8(), QCryptographicHash::Sha256 ).toHex() );\r\n\r\n}\r\n\r\n\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::writeTamperResponse( const QString& response )\r\n\r\n{\r\n\r\n\tconst auto responsePath = QDir( QCoreApplication::applicationDirPath() ).filePath(\r\n\r\n\t\tQStringLiteral( \"acessos_tamper_response.txt\" ) );\r\n\r\n\r\n\r\n\tQFile file( responsePath );\r\n\r\n\tif( file.open( QIODevice::WriteOnly | QIODevice::Text | QIODevice::Truncate ) )\r\n\r\n\t{\r\n\r\n\t\tfile.write( response.toUtf8() );\r\n\r\n\t}\r\n\r\n}\r\n\r\n\r\n\r\nTamperLogProtector::TamperLogProtector( FeatureWorkerManager& featureWorkerManager, QObject* parent ) :\r\n\r\n\tQObject( parent ),\r\n\r\n\tm_featureWorkerManager( featureWorkerManager )\r\n\r\n{\r\n\r\n\trefreshBackups();\r\n\r\n\tauto* pollTimer = new QTimer( this );\r\n\r\n\tconnect( pollTimer, &QTimer::timeout, this, [this]() {\r\n\r\n\t\tcheckNetworkAccessFile();\r\n\r\n\t\tcheckNetworkFile();\r\n\r\n\t} );\r\n\r\n\tpollTimer->start( 1000 );\r\n\r\n\tVeyonCore::builtinFeatures().systemTrayIcon().ensureSessionWorker( m_featureWorkerManager );\r\n\r\n}\r\n\r\n\r\n\r\nbool TamperLogProtector::isAccessLogPath( const QString& filePath ) const\r\n\r\n{\r\n\r\n\treturn filePath == AccessLogWriter::networkAccessLogPath();\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::setWatcherSuppressed( bool suppressed )\r\n\r\n{\r\n\r\n\tif( suppressed )\r\n\r\n\t{\r\n\r\n\t\t++m_suppressWatcherDepth;\r\n\r\n\t}\r\n\r\n\telse if( m_suppressWatcherDepth > 0 )\r\n\r\n\t{\r\n\r\n\t\t--m_suppressWatcherDepth;\r\n\r\n\t}\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::beginProtectedBatch()\r\n\r\n{\r\n\r\n\tsetWatcherSuppressed( true );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::endProtectedBatch()\r\n\r\n{\r\n\r\n\trefreshBackups();\r\n\r\n\tsetWatcherSuppressed( false );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::refreshBackups()\r\n\r\n{\r\n\r\n\tQString content;\r\n\r\n\r\n\r\n\tif( AccessLogWriter::tryReadLogFileContent( AccessLogWriter::networkAccessLogPath(), content ) )\r\n\r\n\t{\r\n\r\n\t\tm_networkAccessBackup = content;\r\n\r\n\t}\r\n\r\n\tif( AccessLogWriter::tryReadLogFileContent( AccessLogWriter::networkTamperedLogPath(), content ) )\r\n\r\n\t{\r\n\r\n\t\tm_networkBackup = content;\r\n\r\n\t}\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::prepareWrite( const QString& filePath )\r\n\r\n{\r\n\r\n\tQ_UNUSED( filePath )\r\n\r\n\tsetWatcherSuppressed( true );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::finalizeWrite( const QString& filePath )\r\n\r\n{\r\n\r\n\tupdateBackupForPath( filePath );\r\n\r\n\tsetWatcherSuppressed( false );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::updateBackupForPath( const QString& filePath )\r\n\r\n{\r\n\r\n\tQString content;\r\n\r\n\r\n\r\n\tif( filePath == AccessLogWriter::networkAccessLogPath() )\r\n\r\n\t{\r\n\r\n\t\tif( AccessLogWriter::tryReadLogFileContent( filePath, content ) )\r\n\r\n\t\t{\r\n\r\n\t\t\tm_networkAccessBackup = content;\r\n\r\n\t\t}\r\n\r\n\t}\r\n\r\n\telse if( filePath == AccessLogWriter::networkTamperedLogPath() )\r\n\r\n\t{\r\n\r\n\t\tif( AccessLogWriter::tryReadLogFileContent( filePath, content ) )\r\n\r\n\t\t{\r\n\r\n\t\t\tm_networkBackup = content;\r\n\r\n\t\t}\r\n\r\n\t}\r\n\r\n}\r\n\r\n\r\n\r\nbool TamperLogProtector::verifyAdminPassword( const QString& password )\r\n\r\n{\r\n\r\n\treturn passwordSha256Hex( password ) == QLatin1String( AdminPasswordHash );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::reportUnauthorizedChange( const QString& filePath, const QString& fileLabel )\r\n\r\n{\r\n\r\n\tvWarning() << \"[tamper-log-protection] unauthorized change detected on\" << fileLabel;\r\n\r\n\r\n\r\n\tif( isAccessLogPath( filePath ) && QFile::exists( filePath ) )\r\n\r\n\t{\r\n\r\n\t\tAccessLogWriter::recordTamperAlertForAccessLogTamper( filePath, QStringLiteral( \"rede\" ) );\r\n\r\n\t}\r\n\r\n\r\n\r\n\tupdateBackupForPath( filePath );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::checkProtectedFile( const QString& filePath, const QString& backup, const QString& fileLabel )\r\n\r\n{\r\n\r\n\tif( isWatcherSuppressed() )\r\n\r\n\t{\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tif( QFile::exists( filePath ) == false )\r\n\r\n\t{\r\n\r\n\t\tif( backup.isEmpty() == false )\r\n\r\n\t\t{\r\n\r\n\t\t\treportUnauthorizedChange( filePath, fileLabel );\r\n\r\n\t\t}\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tQString currentContent;\r\n\r\n\tif( AccessLogWriter::tryReadLogFileContent( filePath, currentContent ) == false )\r\n\r\n\t{\r\n\r\n\t\tvWarning() << \"[tamper-log-protection] skipping check due to read failure on\" << fileLabel;\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tif( AccessLogWriter::logContentsEqual( currentContent, backup ) )\r\n\r\n\t{\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tif( AccessLogWriter::isLegitimateProtectedLogAppend( backup, currentContent ) )\r\n\r\n\t{\r\n\r\n\t\tupdateBackupForPath( filePath );\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tQString retryContent;\r\n\r\n\tQThread::msleep( 400 );\r\n\r\n\tif( AccessLogWriter::tryReadLogFileContent( filePath, retryContent ) &&\r\n\r\n\t\tAccessLogWriter::isLegitimateProtectedLogAppend( backup, retryContent ) )\r\n\r\n\t{\r\n\r\n\t\tupdateBackupForPath( filePath );\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\tif( isAccessLogPath( filePath ) && AccessLogWriter::accessLogFileHasValidIntegrity( filePath ) )\r\n\r\n\t{\r\n\r\n\t\tvDebug() << \"[tamper-log-protection] ignoring change on access log with valid hashes\";\r\n\r\n\t\tupdateBackupForPath( filePath );\r\n\r\n\t\treturn;\r\n\r\n\t}\r\n\r\n\r\n\r\n\treportUnauthorizedChange( filePath, fileLabel );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::checkNetworkAccessFile()\r\n\r\n{\r\n\r\n\tcheckProtectedFile( AccessLogWriter::networkAccessLogPath(), m_networkAccessBackup,\r\n\r\n\t\t\t\t\t\tQStringLiteral( \"rede acessos_veyon\" ) );\r\n\r\n}\r\n\r\n\r\n\r\nvoid TamperLogProtector::checkNetworkFile()\r\n\r\n{\r\n\r\n\tcheckProtectedFile( AccessLogWriter::networkTamperedLogPath(), m_networkBackup,\r\n\r\n\t\t\t\t\t\tQStringLiteral( \"rede acessos_veyon_ad\" ) );\r\n\r\n}\r\n\r\n\r\n\r\n",
