        "code": "/*\r\n\r\n * TamperLogProtector.h - watches access logs and records tamper alerts\r\n\r\n */\r\n\r\n\r\n\r\n#pragma once\r\n\r\n\r\n\r\n#include <QObject>\r\n\r\n\r\n\r\nclass FeatureWorkerManager;\r\n\r\n\r\n\r\nclass TamperLogProtector : public QObject\r\n\r\n{\r\n\r\n\tQ_OBJECT\r\n\r\npublic:\r\n\r\n\texplicit TamperLogProtector( FeatureWorkerManager& featureWorkerManager, QObject* parent = nullptr );\r\n\r\n\r\n\r\n\tvoid refreshBackups();\r\n\r\n\tvoid prepareWrite( const QString& filePath );\r\n\r\n\tvoid finalizeWrite( const QString& filePath );\r\n\r\n\tvoid beginProtectedBatch();\r\n\r\n\tvoid endProtectedBatch();\r\n\r\n\r\n\r\n\tstatic bool verifyAdminPassword( const QString& password );\r\n\r\n\tstatic void writeTamperResponse( const QString& response );\r\n\r\n\r\n\r\nprivate:\r\n\r\n\tbool isAccessLogPath( const QString& filePath ) const;\r\n\r\n\r\n\r\n\tvoid reportUnauthorizedChange( const QString& filePath, const QString& fileLabel );\r\n\r\n\tvoid checkNetworkAccessFile();\r\n\r\n\tvoid checkNetworkFile();\r\n\r\n\tvoid checkProtectedFile( const QString& filePath, const QString& backup, const QString& fileLabel );\r\n\r\n\tvoid updateBackupForPath( const QString& filePath );\r\n\r\n\r\n\r\n\tFeatureWorkerManager& m_featureWorkerManager;\r\n\r\n\r\n\r\n\tQString m_networkAccessBackup;\r\n\r\n\tQString m_networkBackup;\r\n\r\n\tint m_suppressWatcherDepth = 0;\r\n\r\n\r\n\r\n\tbool isWatcherSuppressed() const { return m_suppressWatcherDepth > 0; }\r\n\r\n\tvoid setWatcherSuppressed( bool suppressed );\r\n\r\n\r\n\r\n};\r\n\r\n\r\n\r\n",
