        "file": "server/src/ComputerControlServer.cpp",
        "code": "/*\r\n * ComputerControlServer.cpp - implementation of ComputerControlServer\r\n *\r\n * Copyright (c) 2006-2026 Tobias Junghans <tobydox@veyon.io>\r\n *\r\n * This file is part of Veyon - https://veyon.io\r\n *\r\n * This program is free software; you can redistribute it and/or\r\n * modify it under the terms of the GNU General Public\r\n * License as published by the Free Software Foundation; either\r\n * version 2 of the License, or (at your option) any later version.\r\n *\r\n * This program is distributed in the hope that it will be useful,\r\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\r\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the GNU\r\n * General Public License for more details.\r\n *\r\n * You should have received a copy of the GNU General Public\r\n * License along with this program (see COPYING); if not, write to the\r\n * Free Software Foundation, Inc., 59 Temple Place - Suite 330,\r\n * Boston, MA 02111-1307, USA.\r\n *\r\n */\r\n\r\n#include <QCoreApplication>\r\n#include <QDataStream>\r\n#include <QDir>\r\n#include <QFile>\r\n#include <QLocalSocket>\r\n#include <QTextStream>\r\n#include <QStringConverter>\r\n#include <QDateTime>\r\n#include <QHostInfo>\r\n#include <QNetworkInterface>\r\n\r\n#include \"AccessLogWriter.h\"\r\n#include \"AccessControlProvider.h\"\r\n#include \"BuiltinFeatures.h\"\r\n#include \"CimedVersionAlertMonitor.h\"\r\n#include \"ComputerControlClient.h\"\r\n#include \"ComputerControlServer.h\"\r\n#include \"ComputerSupportInfo.h\"\r\n#include \"FeatureManager.h\"\r\n#include \"FeatureMessage.h\"\r\n#include \"HostAddress.h\"\r\n#include \"Logger.h\"\r\n#include \"PlatformPluginInterface.h\"\r\n#include \"VeyonConfiguration.h\"\r\n#include \"SystemTrayIcon.h\"\r\n\r\nnamespace\r\n{\r\n\r\nbool isLoopbackClientAddress( const QString& ip )\r\n{\r\n\treturn ip == QLatin1String( \"127.0.0.1\" ) ||\r\n\t\t   ip == QLatin1String( \"::1\" ) ||\r\n\t\t   ip == QLatin1String( \"0:0:0:0:0:0:0:1\" );\r\n}\r\n\r\nQString firstNonLoopbackIpv4()\r\n{\r\n\tconst auto addresses = QNetworkInterface::allAddresses();\r\n\tfor( const auto& addr : addresses )\r\n\t{\r\n\t\tif( addr.protocol() == QAbstractSocket::IPv4Protocol && !addr.isLoopback() )\r\n\t\t{\r\n\t\t\treturn addr.toString();\r\n\t\t}\r\n\t}\r\n\r\n\treturn {};\r\n}\r\n\r\nQString normalizeIpAddress( const QString& ipAddress )\r\n{\r\n\tstatic const auto ipv4MappedPrefix = QStringLiteral(\"::ffff:\");\r\n\tif( ipAddress.startsWith( ipv4MappedPrefix, Qt::CaseInsensitive ) )\r\n\t{\r\n\t\treturn ipAddress.mid( ipv4MappedPrefix.size() );\r\n\t}\r\n\r\n\treturn ipAddress;\r\n}\r\n\r\nQString resolvedHostName( const QString& ipAddress )\r\n{\r\n\tconst auto normalizedIpAddress = normalizeIpAddress( ipAddress );\r\n\tconst auto hostInfo = QHostInfo::fromName( normalizedIpAddress );\r\n\tif( hostInfo.error() == QHostInfo::NoError && !hostInfo.hostName().isEmpty() )\r\n\t{\r\n\t\treturn hostInfo.hostName();\r\n\t}\r\n\r\n\treturn normalizedIpAddress;\r\n}\r\n\r\nQString formatElapsedTime( qint64 elapsedMilliseconds )\r\n{\r\n\tconst auto totalSeconds = qMax<qint64>( 0, elapsedMilliseconds / 1000 );\r\n\tconst auto hours = totalSeconds / 3600;\r\n\tconst auto minutes = (totalSeconds % 3600) / 60;\r\n\tconst auto seconds = totalSeconds % 60;\r\n\r\n\tif( hours > 0 )\r\n\t{\r\n\t\treturn QStringLiteral( \"%1:%2:%3\" )\r\n\t\t\t\t.arg( hours, 2, 10, QLatin1Char('0') )\r\n\t\t\t\t.arg( minutes, 2, 10, QLatin1Char('0') )\r\n\t\t\t\t.arg( seconds, 2, 10, QLatin1Char('0') );\r\n\t}\r\n\r\n\treturn QStringLiteral( \"%1:%2\" )\r\n\t\t\t.arg( minutes, 2, 10, QLatin1Char('0') )\r\n\t\t\t.arg( seconds, 2, 10, QLatin1Char('0') );\r\n}\r\n\r\nQString trayErrorMessageForAuthFailure( VncServerClient* client )\r\n{\r\n\tswitch( client->authFailureReason() )\r\n\t{\r\n\tcase VncServerClient::AuthFailureReason::Password:\r\n\t\treturn QStringLiteral( \"Estado: Senha incorreta\" );\r\n\tcase VncServerClient::AuthFailureReason::Login:\r\n\t\treturn QStringLiteral( \"Estado: Erro de login\" );\r\n\tcase VncServerClient::AuthFailureReason::Connection:\r\n\tdefault:\r\n\t\treturn QStringLiteral( \"Estado: Erro de conexao\" );\r\n\t}\r\n}\r\n\r\n}\r\n\r\n\r\nComputerControlServer::ComputerControlServer( QObject* parent ) :\r\n\tVeyonServerInterface(parent),\r\n\tm_allowedIPs(),\r\n\tm_failedAuthHosts(),\r\n\tm_featureWorkerManager( *this ),\r\n\tm_serverAuthenticationManager( this ),\r\n\tm_serverAccessControlManager( m_featureWorkerManager, VeyonCore::builtinFeatures().desktopAccessDialog(), this ),\r\n\tm_vncServer(),\r\n\tm_vncProxyServer( VeyonCore::config().localConnectOnly() || VeyonCore::builtinFeatures().accessControlProvider().isAccessToLocalComputerDenied() ?\r\n\t\t\t\t\t\t  QHostAddress::LocalHost : QHostAddress::Any,\r\n\t\t\t\t\t  VeyonCore::config().veyonServerPort() + VeyonCore::sessionId(),\r\n\t\t\t\t\t  this,\r\n\t\t\t\t\t  this )\r\n{\r\n\tm_trayUpdateTimer.setInterval( 1000 );\r\n\tconnect( &m_trayUpdateTimer, &QTimer::timeout, this, &ComputerControlServer::updateTrayIconToolTip );\r\n\r\n\tupdateTrayIconToolTip();\r\n\r\n\t// make app terminate once the VNC server thread has finished\r\n\tconnect( &m_vncServer, &VncServer::finished, QCoreApplication::instance(), &QCoreApplication::quit );\r\n\r\n\tconnect( &m_serverAuthenticationManager, &ServerAuthenticationManager::finished,\r\n\t\t\t this, &ComputerControlServer::showAuthenticationMessage );\r\n\r\n\tconnect( &m_serverAccessControlManager, &ServerAccessControlManager::finished,\r\n\t\t\t this, &ComputerControlServer::showAccessControlMessage );\r\n\r\n\tconnect(&m_vncProxyServer, &VncProxyServer::serverMessageProcessed,\r\n\t\t\t this, &ComputerControlServer::sendAsyncFeatureMessages, Qt::DirectConnection);\r\n\tconnect(&m_vncProxyServer, &VncProxyServer::serverMessageProcessed,\r\n\t\t\t this, &ComputerControlServer::updateTrayIconToolTip, Qt::DirectConnection);\r\n\tconnect( &m_vncProxyServer, &VncProxyServer::connectionClosed, this, &ComputerControlServer::handleProxyConnectionClosed );\r\n\r\n\tm_localTrayServer = new QLocalServer( this );\r\n\tQLocalServer::removeServer( SystemTrayIcon::localTrayServerName() );\r\n\tif( m_localTrayServer->listen( SystemTrayIcon::localTrayServerName() ) )\r\n\t{\r\n\t\tconnect( m_localTrayServer, &QLocalServer::newConnection, this, &ComputerControlServer::handleLocalTrayNotification );\r\n\t}\r\n\telse\r\n\t{\r\n\t\tvWarning() << \"[tray][local-notify] could not listen on\" << SystemTrayIcon::localTrayServerName();\r\n\t}\r\n}\r\n\r\n\r\n\r\nComputerControlServer::~ComputerControlServer()\r\n{\r\n\tvDebug();\r\n\r\n\tm_vncProxyServer.stop();\r\n}\r\n\r\n\r\n\r\nbool ComputerControlServer::start()\r\n{\r\n\tAccessLogWriter::startTamperedLogProtection( m_featureWorkerManager, this );\r\n\tAccessLogWriter::validateAccessLogsOnStartup();\r\n\tAccessLogWriter::scheduleDailyAccessLogValidation( this );\r\n\tVeyonCore::builtinFeatures().systemTrayIcon().ensureSessionWorker( m_featureWorkerManager );\r\n\r\n\tif( m_vncProxyServer.start( m_vncServer.serverPort(), m_vncServer.password() ) == false )\r\n\t{\r\n\t\treturn false;\r\n\t}\r\n\r\n\tm_vncServer.prepare();\r\n\tm_vncServer.start();\r\n\r\n\tCimedVersionAlertMonitor::startOnSentinelHosts( m_featureWorkerManager, this );\r\n\r\n\treturn true;\r\n}\r\n\r\n\r\n\r\nVncProxyConnection* ComputerControlServer::createVncProxyConnection( QTcpSocket* clientSocket,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t int vncServerPort,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t const Password& vncServerPassword,\r\n\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t\t QObject* parent )\r\n{\r\n\tauto client = new ComputerControlClient( this, cli\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
        "implementation": [
          "path: server/src/ComputerControlServer.cpp",
          "GitHub: https://github.com/CanonEngineer/CustomizeVeyonProject/blob/main/server/src/ComputerControlServer.cpp"
        ]
