        "title": "contact.ejs",
        "description": "Código-fonte: `views/contact.ejs`",
        "file": "views/contact.ejs",
        "code": "<!DOCTYPE html>\r\n<html lang=\"pt-br\">\r\n\t\r\n\t<%- include(\"inc/head\") -%>\t\t\r\n    \r\n<body id=\"principal\">\r\n\t<%- include(\"inc/header-menu\") -%>\r\n    <main id=\"principal\">\r\n\t\t<div id=\"topo\"></div>\r\n\t\t<h1 class=\"topo\">Entre em contato conosco</h1>\r\n\r\n        <div id=\"alerts\">\r\n            <%- include('inc/alerts') -%>\r\n        </div>   \r\n         \r\n        <div class=\"jumboto\">\r\n            <form name=\"meu_form\" class=\"data-ax-form\" action=\"/contact\" method=\"post\">  \r\n                <fieldset> \r\n                    <legend></legend>         \r\n                    <p class=\"nome\">\r\n                    <label class=\"label\">Nome:</label>    \r\n                    <input class=\"space\" type=\"text\" id=\"nomeid\" placeholder=\"Digite o nome\" name=\"name\" value=\"<%= body.name %>\" />\r\n                    <label for=\"nome\"></label>\r\n                    </p>\r\n                    <p class=\"fone\">\r\n                    <label class=\"label\">Telefone:</label>      \r\n                    <input class=\"space\" type=\"text\" id=\"foneid\" placeholder=\"Digite o telefone\" name=\"phone\" value=\"<%= body.phone %>\" />\r\n                    <label for=\"fone\"></label>\r\n                    </p>\r\n                    <p>\r\n                    <label class=\"label\">E-mail:</label>  \r\n                    <input  class=\"space\" type=\"email\" id=\"emailid\" placeholder=\"Digite o seu email\" name=\"email\" value=\"<%= body.email %>\" />\r\n                    <label for=\"email\"></label>\r\n                    </p>\r\n                    <p>\r\n                    <label class=\"label\">Mensagem:</label>  \r\n                    <textarea  class=\"space\"  name=\"message\" id=\"message\" placeholder=\"Deixe sua mensagem\"><%= body.message %></textarea>\r\n                    </p>                    \r\n                    <p class=\"submit\"> <input type=\"submit\" onclick=\"Enviar();\" value=\"Enviar\" />\r\n                    </p>\r\n                </fieldset>\r\n            </form>\r\n        </div>\r\n\t</main>\r\n\t<%- include(\"inc/footer\") -%>\r\n\t<%- include(\"inc/footer-scripts\") -%>\r\n</body>\r\n</html>",
        "implementation": [
          "path: views/contact.ejs",
          "GitHub: https://github.com/CanonEngineer/SearchUnivespProject/blob/main/views/contact.ejs"
        ]
