        "file": "views/inc/head.ejs",
        "code": "<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Oswald:wght@500&family=Roboto:wght@700&display=swap\" rel=\"stylesheet\"><link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\r\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\r\n    <link href=\"https://fonts.googleapis.com/css2?family=Oswald:wght@500&family=Roboto:wght@700&display=swap\" rel=\"stylesheet\">\r\n    <title><%= title %></title>\r\n    <link rel=\"stylesheet\" href=\"assests/css/reset.css\">\r\n    <link rel=\"stylesheet\" href=\"assests/css/style.css\">\r\n    <link rel=\"stylesheet\" href=\"assests/css/form.css\">\r\n    \r\n</head>",
