        "layer": "file",
        "title": "feature-inventory.json",
        "description": "Código-fonte: `backend/app/data/feature-inventory.json`",
        "file": "backend/app/data/feature-inventory.json",
        "code": "{\r\n  \"version\": \"2026-07-23b\",\r\n  \"project\": \"SentinelAI\",\r\n  \"sections\": {\r\n    \"map_editor\": {\r\n      \"title\": \"Map Editor (The Dude++)\",\r\n      \"items\": [\r\n        { \"id\": \"infinite_canvas\", \"label\": \"Canvas infinito (Infinite Canvas)\", \"status\": \"done\", \"notes\": \"React Flow pan livre — TopologyMap.tsx\" },\r\n        { \"id\": \"zoom\", \"label\": \"Zoom fluido 10%–500%\", \"status\": \"done\", \"notes\": \"minZoom 0.1, maxZoom 5\" },\r\n        { \"id\": \"drag_drop_library\", \"label\": \"Drag-and-drop da biblioteca de equipamentos\", \"status\": \"done\", \"notes\": \"DeviceLibrary.tsx\" },\r\n        { \"id\": \"smart_connectors\", \"label\": \"Conectores inteligentes (anti-cruzamento)\", \"status\": \"done\", \"notes\": \"Auto-layout dagre + ELK\" },\r\n        { \"id\": \"grouping\", \"label\": \"Agrupamento racks, salas, prédios, VLANs, sites\", \"status\": \"done\", \"notes\": \"GroupType: rack, room, building, vlan, site, department\" },\r\n        { \"id\": \"snap_grid\", \"label\": \"Grade magnética (Snap to Grid)\", \"status\": \"done\", \"notes\": \"Grade 20px, toggle na toolbar\" },\r\n        { \"id\": \"alignment_guides\", \"label\": \"Guias de alinhamento inteligentes\", \"status\": \"done\", \"notes\": \"AlignmentGuides.tsx\" },\r\n        { \"id\": \"undo_redo\", \"label\": \"Desfazer/Refazer ilimitado\", \"status\": \"done\", \"notes\": \"Histórico ilimitado em TopologyMap + useMapHistory.ts\" },\r\n        { \"id\": \"minimap\", \"label\": \"Minimap para navegação\", \"status\": \"done\", \"notes\": \"React Flow MiniMap\" },\r\n        { \"id\": \"edge_styles\", \"label\": \"Estilos de conexão (reta, ortogonal, curva)\", \"status\": \"done\", \"notes\": \"straight, step, smoothstep, default\" },\r\n        { \"id\": \"layers\", \"label\": \"Camadas (lógica, física, elétrica, Wi-Fi)\", \"status\": \"done\", \"notes\": \"Filtro map_layer na toolbar\" },\r\n        { \"id\": \"export\", \"label\": \"Exportação PNG, SVG, PDF, Visio\", \"status\": \"done\", \"notes\": \"PNG/SVG client; PDF/VSDX server\" },\r\n        { \"id\": \"realtime_collab\", \"label\": \"Colaboração em tempo real (multi-admin)\", \"status\": \"done\", \"notes\": \"WebSocket /ws/map\" },\r\n        { \"id\": \"auto_update_inventory\", \"label\": \"Atualização automática após inventário\", \"status\": \"done\", \"notes\": \"Poll discovery jobs 5s + SSE inventory_completed + reload mapa\" },\r\n        { \"id\": \"view_2d_3d\", \"label\": \"Visualização 2D e 3D\", \"status\": \"done\", \"notes\": \"TopologyMap + Map3DView.tsx\" },\r\n        { \"id\": \"traffic_animation\", \"label\": \"Animações de tráfego nos links\", \"status\": \"done\", \"notes\": \"TrafficEdge.tsx + SNMP\" },\r\n        { \"id\": \"dynamic_filters\", \"label\": \"Filtros dinâmicos\", \"status\": \"done\", \"notes\": \"Tipo, status, tag + filtro VLAN na toolbar (vlan_id API)\" },\r\n        { \"id\": \"tags\", \"label\": \"Sistema de etiquetas (Tags)\", \"status\": \"done\", \"notes\": \"JSONB tags + filtro API\" }\r\n      ]\r\n    },\r\n    \"nms_platform\": {\r\n      \"title\": \"Plataforma NMS\",\r\n      \"items\": [\r\n        { \"id\": \"discovery_icmp\", \"label\": \"Descoberta automática — ICMP\", \"status\": \"done\", \"notes\": \"subnet_scanner.py, ping pós-nmap, scan /24\" },\r\n        { \"id\": \"discovery_snmp\", \"label\": \"Descoberta automática — SNMP\", \"status\": \"done\", \"notes\": \"snmp_collector.py, LLDP/CDP, traps\" },\r\n        { \"id\": \"discovery_ssh\", \"label\": \"Descoberta automática — SSH\", \"status\": \"done\", \"notes\": \"ssh_collector.py + toggle use_ssh no scan\" },\r\n        { \"id\": \"discovery_wmi\", \"label\": \"Descoberta automática — WMI\", \"status\": \"done\", \"notes\": \"wmi_collector.py (impacket), porta 135, Win32_* queries, toggle use_wmi\" },\r\n        { \"id\": \"dynamic_topology\", \"label\": \"Mapeamento dinâmico da topologia\", \"status\": \"done\", \"notes\": \"LLDP/CDP, auto-cadastro, job horário Celery\" },\r\n        { \"id\": \"interactive_diagrams\", \"label\": \"Diagramas interativos da infraestrutura\", \"status\": \"done\", \"notes\": \"TopologyMap 2D/3D editável\" },\r\n        { \"id\": \"realtime_monitoring\", \"label\": \"Monitoramento em tempo real\", \"status\": \"done\", \"notes\": \"SSE /api/stream/monitoring + eventos device_status/inventory\" },\r\n        { \"id\": \"hw_inventory\", \"label\": \"Inventário de hardware\", \"status\": \"done\", \"notes\": \"GET /api/devices/{id}/hardware + aba Hardware (serial, ports, SNMP)\" },\r\n        { \"id\": \"sw_inventory\", \"label\": \"Inventário de software\", \"status\": \"done\", \"notes\": \"software_collector.py SNMP hrSW + WMI, GET/POST /api/devices/{id}/software\" },\r\n        { \"id\": \"alerts_email\", \"label\": \"Alertas por e-mail\", \"status\": \"done\", \"notes\": \"engines/alerts/email.py\" },\r\n        { \"id\": \"alerts_sms\", \"label\": \"Alertas por SMS\", \"status\": \"done\", \"notes\": \"engines/alerts/sms.py via Twilio REST API\" },\r\n        { \"id\": \"alerts_apps\", \"label\": \"Alertas por aplicativos\", \"status\": \"done\", \"notes\": \"Telegram/Slack/Discord/Teams/Webhook + push Expo mobile\" },\r\n        { \"id\": \"custom_dashboards\", \"label\": \"Dashboards personalizáveis\", \"status\": \"done\", \"notes\": \"useDashboardLayout — show/hide/reorder widgets + localStorage\" },\r\n        { \"id\": \"device_monitoring\", \"label\": \"Monitor servers/switches/routers/firewalls/printers/APs\", \"status\": \"done\", \"notes\": \"Tipo firewall + inferência SNMP + FortinetPlugin REST\" },\r\n        { \"id\": \"vm_cloud_monitoring\", \"label\": \"Monitor VMs e ambientes nuvem\", \"status\": \"done\", \"notes\": \"Plugins Proxmox/VMware/AWS/Azure + sync Celery → Device VM\" },\r\n        { \"id\": \"performance_history\", \"label\": \"Histórico de desempenho e relatórios\", \"status\": \"done\", \"notes\": \"metrics, SLA, PDF/XLSX, SOC2, anomalias, IA\" },\r\n        { \"id\": \"integration_apis\", \"label\": \"APIs para integração\", \"status\": \"done\", \"notes\": \"REST FastAPI /docs, Zabbix/PRTG export, webhooks\" }\r\n      ]\r\n    }\r\n  },\r\n  \"status_labels\": {\r\n    \"done\": \"✅ Implementado\",\r\n    \"partial\": \"⚠️ Parcial\",\r\n    \"missing\": \"❌ Ausente\"\r\n  },\r\n  \"key_files\": [\r\n    \"frontend/src/pages/TopologyMap.tsx\",\r\n    \"frontend/src/components/map/MapToolbar.tsx\",\r\n    \"frontend/src/pages/Dashboard.tsx\",\r\n    \"backend/app/workers/discovery_tasks.py\",\r\n    \"backend/app/services/monitor_service.py\",\r\n    \"backend/app/engines/alerts/channels.py\",\r\n    \"backend/app/engines/alerts/sms.py\",\r\n    \"backend/app/engines/discovery/wmi_collector.py\",\r\n    \"backend/app/engines/discovery/software_collector.py\",\r\n    \"backend/app/engines/discovery/ssh_collector.py\",\r\n    \"backend/app/engines/alerts/push.py\",\r\n    \"backend/app/services/realtime_events.py\",\r\n    \"backend/app/services/plugin_sync_service.py\",\r\n    \"backend/app/services/hardware_service.py\",\r\n    \"frontend/src/hooks/useDashboardLayout.ts\",\r\n    \"frontend/src/hooks/useMonitoringStream.ts\",\r\n    \"docs/MAP-EDITOR-ROADMAP.md\"\r\n  ]\r\n}\r\n",
