        "file": "backend/scripts/smoke_phase21.py",
        "code": "#!/usr/bin/env python3\r\n\"\"\"Smoke test Fase 21 endpoints.\"\"\"\r\n\r\nimport json\r\nimport sys\r\nimport time\r\nimport urllib.error\r\nimport urllib.parse\r\nimport urllib.request\r\n\r\nBASE = \"http://127.0.0.1:8000\"\r\n\r\n\r\ndef req(method: str, path: str, token: str | None = None, data: dict | None = None) -> tuple[int, object]:\r\n    headers = {\"Content-Type\": \"application/json\"}\r\n    if token:\r\n        headers[\"Authorization\"] = f\"Bearer {token}\"\r\n    body = json.dumps(data).encode() if data is not None else None\r\n    request = urllib.request.Request(BASE + path, data=body, headers=headers, method=method)\r\n    try:\r\n        with urllib.request.urlopen(request, timeout=15) as resp:\r\n            raw = resp.read().decode()\r\n            return resp.status, json.loads(raw) if raw else {}\r\n    except urllib.error.HTTPError as exc:\r\n        return exc.code, exc.read().decode()\r\n\r\n\r\ndef req_form(path: str, form: dict[str, str]) -> tuple[int, object]:\r\n    body = urllib.parse.urlencode(form).encode()\r\n    request = urllib.request.Request(\r\n        BASE + path,\r\n        data=body,\r\n        headers={\"Content-Type\": \"application/x-www-form-urlencoded\"},\r\n        method=\"POST\",\r\n    )\r\n    with urllib.request.urlopen(request, timeout=15) as resp:\r\n        return resp.status, json.loads(resp.read().decode())\r\n\r\n\r\ndef main() -> int:\r\n    for _ in range(20):\r\n        try:\r\n            with urllib.request.urlopen(BASE + \"/health\", timeout=5) as resp:\r\n                if resp.status == 200:\r\n                    break\r\n        except Exception:\r\n            pass\r\n        time.sleep(1)\r\n    else:\r\n        print(\"FAIL API not ready\")\r\n        return 1\r\n\r\n    status, login = req_form(\"/api/auth/login\", {\"username\": \"admin\", \"password\": \"admin123\"})\r\n    if status != 200:\r\n        print(\"FAIL login\", status, login)\r\n        return 1\r\n    token = login[\"access_token\"]\r\n\r\n    _, system = req(\"GET\", \"/api/system/status\", token)\r\n    print(f\"VERSION {system.get('version') if isinstance(system, dict) else system}\")\r\n\r\n    checks = []\r\n\r\n    def check(name: str, method: str, path: str, data: dict | None = None) -> None:\r\n        st, body = req(method, path, token, data)\r\n        ok = st == 200\r\n        checks.append((name, ok, st, body))\r\n        print(f\"{'PASS' if ok else 'FAIL'} {name} -> {st}\")\r\n\r\n    check(\"billing/tax/regions\", \"GET\", \"/api/billing/tax/regions\")\r\n    check(\"billing/tax/quote\", \"POST\", \"/api/billing/tax/quote\", {\"amount_cents\": 9900, \"region_code\": \"EU\", \"currency\": \"EUR\"})\r\n    check(\"marketplace reviews list\", \"GET\", \"/api/scale/playbooks/marketplace/reviews?playbook_slug=mp-dns-flush\")\r\n    check(\"marketplace with ratings\", \"GET\", \"/api/scale/playbooks/marketplace\")\r\n    check(\"vision webxr\", \"GET\", \"/api/vision/webxr?map_layer=physical\")\r\n    check(\"cdn auto-purge\", \"POST\", \"/api/cdn/auto-purge\")\r\n    check(\"auditor tenant billing\", \"GET\", \"/api/auditor/tenants/billing\")\r\n\r\n    failed = [c for c in checks if not c[1]]\r\n    print(\"---\")\r\n    print(f\"Results: {len(checks) - len(failed)}/{len(checks)} passed\")\r\n    return 0 if not failed else 1\r\n\r\n\r\nif __name__ == \"__main__\":\r\n    sys.exit(main())\r\n",
