        "file": "frontend/src/context/MapActionsContext.tsx",
        "code": "import { createContext, useContext, type ReactNode } from \"react\";\r\n\r\ninterface MapActionsContextValue {\r\n  canWrite: boolean;\r\n  onDeleteDevice: (deviceId: number, deviceLabel: string, ip: string) => void;\r\n  onDeleteDepartment?: (groupId: number, name: string) => void;\r\n}\r\n\r\nconst MapActionsContext = createContext<MapActionsContextValue>({\r\n  canWrite: false,\r\n  onDeleteDevice: () => undefined,\r\n});\r\n\r\nexport function MapActionsProvider({\r\n  canWrite,\r\n  onDeleteDevice,\r\n  onDeleteDepartment,\r\n  children,\r\n}: MapActionsContextValue & { children: ReactNode }) {\r\n  return (\r\n    <MapActionsContext.Provider value={{ canWrite, onDeleteDevice, onDeleteDepartment }}>\r\n      {children}\r\n    </MapActionsContext.Provider>\r\n  );\r\n}\r\n\r\nexport function useMapActions(): MapActionsContextValue {\r\n  return useContext(MapActionsContext);\r\n}\r\n",
