        "file": "frontend/src/pages/Dashboard.tsx",
        "code": "import { useCallback, useEffect, useMemo, useState } from \"react\";\nimport {\n  Activity,\n  CheckCircle2,\n  ChevronLeft,\n  ChevronRight,\n  Plus,\n  Radar,\n  Square,\n  Upload,\n  Wifi,\n  WifiOff,\n} from \"lucide-react\";\nimport {\n  createDevice,\n  clearToken,\n  fetchDevice,\n  fetchDeviceHistory,\n  enrichDevice,\n  fetchDevices,\n  fetchDiscoveryJobs,\n  fetchEvents,\n  fetchScanDefaults,\n  importCsv,\n  startDiscovery,\n  stopDiscoveryJob,\n  DEFAULT_SCAN_OPTIONS,\n  type Device,\n  type DeviceHistoryEntry,\n  type DiscoveryJob,\n  type Event,\n  type ScanDefaultsResponse,\n  type ScanOptionsPayload,\n} from \"../api/client\";\nimport DeviceList, { DeviceDetailPanel } from \"../components/DeviceList\";\nimport DeviceStatusChart from \"../components/DeviceStatusChart\";\nimport DeviceTypeBreakdown from \"../components/DeviceTypeBreakdown\";\nimport DiscoveryJobProgress, {\n  DiscoveryJobActiveBanner,\n  discoveryJobCounts,\n} from \"../components/DiscoveryJobProgress\";\nimport DiscoveryScanOptions from \"../components/DiscoveryScanOptions\";\nimport StatCard from \"../components/ui/StatCard\";\nimport StatusBadge from \"../components/ui/StatusBadge\";\nimport DataTable, { type Column } from \"../components/ui/DataTable\";\nimport { useAuth } from \"../context/AuthContext\";\nimport { useDashboardLayout, DASHBOARD_WIDGET_LABELS } from \"../hooks/useDashboardLayout\";\nimport { useMonitoringStream } from \"../hooks/useMonitoringStream\";\n\nexport default function Dashboard() {\n  const { canWrite } = useAuth();\n  const [devices, setDevices] = useState<Device[]>([]);\n  const [events, setEvents] = useState<Event[]>([]);\n  const [eventsPage, setEventsPage] = useState(0);\n  const [jobs, setJobs] = useState<DiscoveryJob[]>([]);\n  const [ip, setIp] = useState(\"\");\n  const [hostname, setHostname] = useState(\"\");\n  const [subnet, setSubnet] = useState(\"192.168.1.0/24\");\n  const [message, setMessage] = useState<{ type: \"success\" | \"error\" | \"info\"; text: string } | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [selectedDevice, setSelectedDevice] = useState<Device | null>(null);\n  const [deviceHistory, setDeviceHistory] = useState<DeviceHistoryEntry[]>([]);\n  const [enrichingDevice, setEnrichingDevice] = useState(false);\n  const [stoppingJobId, setStoppingJobId] = useState<number | null>(null);\n  const [trackedJobId, setTrackedJobId] = useState<number | null>(null);\n  const [startingScan, setStartingScan] = useState(false);\n  const [scanOptions, setScanOptions] = useState<ScanOptionsPayload>(DEFAULT_SCAN_OPTIONS);\n  const [scanDefaults, setScanDefaults] = useState<ScanDefaultsResponse | null>(null);\n  const [customizeOpen, setCustomizeOpen] = useState(false);\n  const { layout, toggleWidget, moveWidget, resetLayout, isVisible } = useDashboardLayout();\n\n  useMonitoringStream((type) => {\n    if (type === \"inventory_completed\" || type === \"device_status_changed\") {\n      void loadData();\n    }\n  });\n\n  const pollDiscoveryJobs = useCallback(async () => {\n    try {\n      const jobList = await fetchDiscoveryJobs();\n      setJobs(jobList);\n    } catch {\n      /* ignore poll errors */\n    }\n  }, []);\n\n  const loadData = useCallback(async () => {\n    const maxAttempts = 2;\n    let lastError: unknown;\n    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {\n      try {\n        const [deviceList, eventList, jobList] = await Promise.all([\n          fetchDevices({ onMap: true, limit: 2500 }),\n          fetchEvents(100),\n          fetchDiscoveryJobs(),\n        ]);\n        setDevices(deviceList.slice(0, 2500));\n        setEvents(eventList.slice(0, 100));\n        setJobs(jobList);\n        return;\n      } catch (err) {\n        lastError = err;\n        const status = (err as Error & { status?: number }).status;\n        const msg = err instanceof Error ? err.message : String(err);\n        if (status === 401 || msg.includes(\"401\") || msg.toLowerCase().includes(\"unauthorized\")) {\n          throw err;\n        }\n        if (attempt < maxAttempts) {\n          await new Promise((resolve) => setTimeout(resolve, 1000));\n        }\n      }\n    }\n    throw lastError;\n  }, []);\n\n  useEffect(() => {\n    const loadingCap = window.setTimeout(() => setLoading(false), 20000);\n    loadData()\n      .catch((err: unknown) => {\n        const status = (err as Error & { status?: number }).status;\n        const msg = err instanceof Error ? err.message : String(err);\n        if (status === 401 || msg.includes(\"401\") || msg.toLowerCase().includes(\"unauthorized\")) {\n          clearToken();\n          setMessage({ type: \"info\", text: \"Sessão expirada. Faça login novamente.\" });\n          window.setTimeout(() => window.location.reload(), 1200);\n          return;\n        }\n        setMessage({\n          type: \"error\",\n          text: \"Erro ao carregar dados. Verifique se a API está online (http://localhost:8000/health).\",\n        });\n      })\n      .finally(() => {\n        window.clearTimeout(loadingCap);\n        setLoading(false);\n      });\n    const interval = setInterval(() => loadData().catch(() => undefined), 15000);\n    return () => {\n      window.clearTimeout(loadingCap);\n      clearInterval(interval);\n    };\n  }, [loadData]);\n\n  const activeJobs = useMemo(\n    () => jobs.filter((j) => j.status === \"pending\" || j.status === \"running\"),\n    [jobs],\n  );\n\n  const trackedJob = useMemo(\n    () => (trackedJobId ? jobs.find((j) => j.id === trackedJobId) ?? null : null),\n    [jobs, trackedJobId],\n  );\n\n  const bannerJobs = useMemo(() => {\n    if (trackedJob) return [trackedJob];\n    return activeJobs;\n  }, [trackedJob, activeJobs]);\n\n  const EVENTS_PAGE_SIZE = 10;\n  const eventsTotalPages = Math.max(1, Math.ceil(events.length / EVENTS_PAGE_SIZE));\n  const eventsPageSafe = Math.min(eventsPage, eventsTotalPages - 1);\n  const pagedEvents = useMemo(\n    () => events.slice(eventsPageSafe * EVENTS_PAGE_SIZE, (eventsPageSafe + 1) * EVENTS_PAGE_SIZE),\n    [events, eventsPageSafe],\n  );\n\n  useEffect(() => {\n    if (eventsPage !== eventsPageSafe) setEventsPage(eventsPageSafe);\n  }, [eventsPage, eventsPageSafe]);\n\n  const scanBusy = startingScan || activeJobs.length > 0 || trackedJobId !== null;\n\n  useEffect(() => {\n    fetchScanDefaults()\n      .then(setScanDefaults)\n      .catch(() => undefined);\n  }, []);\n\n  useEffect(() => {\n    if (!trackedJobId && activeJobs.length === 0) return undefined;\n    void pollDiscoveryJobs();\n    const tick = window.setInterval(() => {\n      void pollDiscoveryJobs();\n    }, 1500);\n    return () => window.clearInterval(tick);\n  }, [trackedJobId, activeJobs.length, pollDiscoveryJobs]);\n\n  useEffect(() => {\n    if (!trackedJob) return undefined;\n    if (trackedJob.status === \"completed\") {\n      setMessage({ type: \"success\", text: `Scan #${trackedJob.id} concluído · ${trackedJob.subnet}` });\n      void loadData();\n      const t = window.setTimeout(() => setTrackedJobId(null), 6000);\n      return () => window.clearTimeout(t);\n    }\n    if (trackedJob.status === \"failed\") {\n      setMessage({\n        type: \"error\",\n        text: trackedJob.er\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
