        "file": "frontend/src/pages/PlatformPage.tsx",
        "code": "import { useCallback, useEffect, useState } from \"react\";\nimport { Activity, CreditCard, Download, Gauge, GitBranch, Globe, Lock, Monitor, Package, Play, RefreshCw, ScrollText, Shield, Smartphone, Store, Wrench, Zap } from \"lucide-react\";\nimport {\n  analyzeMapVision,\n  createCustomPlaybook,\n  createPaymentCheckout,\n  fetchAuditorWhiteLabel,\n  fetchCdnAnalytics,\n  fetchConsolidatedBilling,\n  fetchCustomPlaybooks,\n  fetchBillingCurrencies,\n  fetchPlaybookMarketplace,\n  fetchCdnCostOptimization,\n  fetchAuditorTenants,\n  fetchAuditorTenantBilling,\n  fetchBillingTaxRegions,\n  fetchVisionWebXr,\n  fetchPlaybookReviews,\n  runCdnAutoPurge,\n  quoteBillingTax,\n  submitPlaybookReview,\n  installPlaybookMarketplace,\n  convertBillingCurrency,\n  downloadSoc2Report,\n  fetchAuditLogs,\n  fetchBillingOverview,\n  fetchCdnManifest,\n  fetchCdnStatus,\n  fetchCopilotLlmStatus,\n  fetchDesktopConfig,\n  fetchEdgeStats,\n  fetchFederationStatus,\n  fetchGitOpsStatus,\n  fetchMarketplace,\n  fetchMeshStatus,\n  fetchMobileBuildStatus,\n  fetchMobileConfig,\n  fetchObservabilityStatus,\n  fetchPaymentInvoices,\n  fetchPaymentStatus,\n  fetchAuditorPortalStatus,\n  fetchAuditorSsoStatus,\n  fetchPendingApprovals,\n  fetchVisionStreamStatus,\n  purgeCdnCache,\n  resolveRemediationApproval,\n  sendInvoiceEmail,\n  type AuditorSsoStatus,\n  type RemediationApproval,\n  type VisionStreamStatus,\n  fetchCdnProviderStatus,\n  fetchRemediationSchedule,\n  simulateStripeWebhook,\n  type AuditorPortalStatus,\n  type AuditorWhiteLabel,\n  type CdnAnalytics,\n  type ConsolidatedBilling,\n  type CustomPlaybook,\n  type CdnProviderStatus,\n  type PaymentInvoice,\n  type RemediationScheduleStatus,\n  fetchRegions,\n  fetchRemediationPlaybooks,\n  fetchRemediationRuns,\n  fetchSystemStatus,\n  fetchTracingStatus,\n  fetchVaultStatus,\n  fetchZeroTrustStatus,\n  generateSoc2Report,\n  generateSoc2Type2Report,\n  installMarketplacePlugin,\n  previewAlertRuleMatch,\n  runRemediation,\n  syncMarketplaceRegistry,\n  type AuditLogEntry,\n  type BillingOverview,\n  type CdnStatus,\n  type CopilotLlmStatus,\n  type EdgeStats,\n  type FederationStatus,\n  type GitOpsStatus,\n  type MarketplacePlugin,\n  type MeshStatus,\n  type MobileBuildStatus,\n  type ObservabilityStatus,\n  type PaymentStatus,\n  type RegionInfo,\n  type RemediationPlaybook,\n  type RemediationRun,\n  type SystemStatus,\n  type TracingStatus,\n  type VaultStatus,\n  type ZeroTrustStatus,\n  type BillingCurrencies,\n  type PlaybookMarketplaceItem,\n  type CdnCostOptimization,\n  type AuditorTenant,\n  type BillingTaxRegions,\n  type VisionWebXr,\n  type CdnAutoPurge,\n  type AuditorTenantBilling,\n  type PlaybookReview,\n} from \"../api/client\";\nimport DataTable, { type Column } from \"../components/ui/DataTable\";\nimport StatCard from \"../components/ui/StatCard\";\nimport StatusBadge from \"../components/ui/StatusBadge\";\n\ntype TabId = \"marketplace\" | \"system\" | \"observability\" | \"gitops\" | \"enterprise\" | \"billing\" | \"autonomous\" | \"production\" | \"scale\" | \"fase20\" | \"fase21\" | \"apps\";\n\nexport default function PlatformPage() {\n  const [tab, setTab] = useState<TabId>(\"marketplace\");\n  const [marketplace, setMarketplace] = useState<MarketplacePlugin[]>([]);\n  const [status, setStatus] = useState<SystemStatus | null>(null);\n  const [observability, setObservability] = useState<ObservabilityStatus | null>(null);\n  const [tracing, setTracing] = useState<TracingStatus | null>(null);\n  const [regions, setRegions] = useState<RegionInfo[]>([]);\n  const [gitops, setGitops] = useState<GitOpsStatus | null>(null);\n  const [mobileBuild, setMobileBuild] = useState<MobileBuildStatus | null>(null);\n  const [auditLogs, setAuditLogs] = useState<AuditLogEntry[]>([]);\n  const [federation, setFederation] = useState<FederationStatus | null>(null);\n  const [vault, setVault] = useState<VaultStatus | null>(null);\n  const [mesh, setMesh] = useState<MeshStatus | null>(null);\n  const [billing, setBilling] = useState<BillingOverview | null>(null);\n  const [edgeStats, setEdgeStats] = useState<EdgeStats | null>(null);\n  const [zeroTrust, setZeroTrust] = useState<ZeroTrustStatus | null>(null);\n  const [copilotLlm, setCopilotLlm] = useState<CopilotLlmStatus | null>(null);\n  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus | null>(null);\n  const [playbooks, setPlaybooks] = useState<RemediationPlaybook[]>([]);\n  const [remediationRuns, setRemediationRuns] = useState<RemediationRun[]>([]);\n  const [cdnStatus, setCdnStatus] = useState<CdnStatus | null>(null);\n  const [mapVision, setMapVision] = useState<{ analysis: string; source: string } | null>(null);\n  const [invoices, setInvoices] = useState<PaymentInvoice[]>([]);\n  const [remSchedule, setRemSchedule] = useState<RemediationScheduleStatus | null>(null);\n  const [cdnProvider, setCdnProvider] = useState<CdnProviderStatus | null>(null);\n  const [auditorPortal, setAuditorPortal] = useState<AuditorPortalStatus | null>(null);\n  const [approvals, setApprovals] = useState<RemediationApproval[]>([]);\n  const [auditorSso, setAuditorSso] = useState<AuditorSsoStatus | null>(null);\n  const [visionStream, setVisionStream] = useState<VisionStreamStatus | null>(null);\n  const [consolidated, setConsolidated] = useState<ConsolidatedBilling | null>(null);\n  const [customPlaybooks, setCustomPlaybooks] = useState<CustomPlaybook[]>([]);\n  const [cdnAnalytics, setCdnAnalytics] = useState<CdnAnalytics | null>(null);\n  const [whiteLabel, setWhiteLabel] = useState<AuditorWhiteLabel | null>(null);\n  const [currencies, setCurrencies] = useState<BillingCurrencies | null>(null);\n  const [playbookMarketplace, setPlaybookMarketplace] = useState<PlaybookMarketplaceItem[]>([]);\n  const [cdnCostOpt, setCdnCostOpt] = useState<CdnCostOptimization | null>(null);\n  const [auditorTenants, setAuditorTenants] = useState<AuditorTenant[]>([]);\n  const [taxRegions, setTaxRegions] = useState<BillingTaxRegions | null>(null);\n  const [webxr, setWebxr] = useState<VisionWebXr | null>(null);\n  const [tenantBilling, setTenantBilling] = useState<AuditorTenantBilling | null>(null);\n  const [playbookReviews, setPlaybookReviews] = useState<PlaybookReview[]>([]);\n  const [mobile, setMobile] = useState<{ pwa_enabled: boolean; app_name: string; short_name: string; theme_color: string } | null>(null);\n  const [desktop, setDesktop] = useState<{ electron_available: boolean; package: string; default_api_url: string; default_frontend_url: string } | null>(null);\n  const [message, setMessage] = useState<string | null>(null);\n  const [rulePreview, setRulePreview] = useState<{ event_type: string; severity: string; channels: string[]; matched_rules: string[] } | null>(null);\n\n  const load = useCallback(async () => {\n    const [m, s, obs, tr, reg, go, mb, aud, fed, vlt, msh, bill, edge, zt, llm, pay, pb, runs, cdn, inv, rsched, cprov, aportal, appr, sso, vstream, cons, cpb, cdnan, wl, cur, pbm, cco, aten, tax, wxr, tbill, mob, desk] = await Promise.all([\n      fetchMarketplace(),\n      fetchSystemStatus(),\n      fetchObservabilityStatus(),\n      fetchTracingStatus()\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
