        "description": "Código-fonte: `frontend/src/pages/ScannerPage.tsx`",
        "file": "frontend/src/pages/ScannerPage.tsx",
        "code": "import { useCallback, useEffect, useMemo, useState } from \"react\";\r\nimport { ScanSearch } from \"lucide-react\";\r\nimport {\r\n  fetchDevices,\r\n  fetchPortScanJobs,\r\n  startPortScan,\r\n  type Device,\r\n  type PortScanJob,\r\n} from \"../api/client\";\r\nimport DataTable, { type Column } from \"../components/ui/DataTable\";\r\nimport StatusBadge from \"../components/ui/StatusBadge\";\r\n\r\nexport default function ScannerPage() {\r\n  const [devices, setDevices] = useState<Device[]>([]);\r\n  const [jobs, setJobs] = useState<PortScanJob[]>([]);\r\n  const [message, setMessage] = useState<string | null>(null);\r\n  const [scanning, setScanning] = useState<number | null>(null);\r\n\r\n  const load = useCallback(async () => {\r\n    const [deviceList, jobList] = await Promise.all([fetchDevices(), fetchPortScanJobs()]);\r\n    setDevices(deviceList);\r\n    setJobs(jobList);\r\n  }, []);\r\n\r\n  useEffect(() => {\r\n    load().catch(() => undefined);\r\n    const interval = setInterval(() => load().catch(() => undefined), 10000);\r\n    return () => clearInterval(interval);\r\n  }, [load]);\r\n\r\n  async function handleScan(deviceId: number) {\r\n    setScanning(deviceId);\r\n    try {\r\n      await startPortScan(deviceId);\r\n      setMessage(\"Scan de portas iniciado.\");\r\n      await load();\r\n    } finally {\r\n      setScanning(null);\r\n    }\r\n  }\r\n\r\n  const deviceColumns: Column<Device>[] = [\r\n      { key: \"ip_address\", header: \"IP\", sortable: true },\r\n      { key: \"hostname\", header: \"Hostname\", render: (d) => d.hostname ?? \"—\" },\r\n      { key: \"status\", header: \"Status\", render: (d) => <StatusBadge status={d.status} /> },\r\n      {\r\n        key: \"actions\",\r\n        header: \"\",\r\n        sortable: false,\r\n        render: (d) => (\r\n          <button\r\n            type=\"button\"\r\n            className=\"sa-btn sa-btn-primary sa-btn-sm\"\r\n            disabled={scanning === d.id}\r\n            onClick={(e) => { e.stopPropagation(); handleScan(d.id); }}\r\n          >\r\n            {scanning === d.id ? <span className=\"sa-spinner\" /> : <ScanSearch size={14} />}\r\n            Escanear\r\n          </button>\r\n        ),\r\n      },\r\n  ];\r\n\r\n  const jobColumns: Column<PortScanJob>[] = useMemo(\r\n    () => [\r\n      { key: \"id\", header: \"Job\", render: (j) => `#${j.id}` },\r\n      { key: \"device_id\", header: \"Device ID\", sortable: true },\r\n      { key: \"status\", header: \"Status\", render: (j) => <StatusBadge status={j.status} /> },\r\n      { key: \"ports_open\", header: \"Abertas\", sortable: true },\r\n      {\r\n        key: \"results\",\r\n        header: \"Portas / Serviços\",\r\n        render: (j) => j.results?.map((r) => `${r.port}/${r.service ?? \"?\"}`).join(\", \") || \"—\",\r\n      },\r\n    ],\r\n    [],\r\n  );\r\n\r\n  return (\r\n    <>\r\n      {message && <div className=\"sa-alert sa-alert-success\">{message}</div>}\r\n\r\n      <div className=\"sa-card\">\r\n        <div className=\"sa-card-header\">\r\n          <div>\r\n            <h2>Dispositivos</h2>\r\n            <p>Selecione um equipamento para scan TCP de portas comuns</p>\r\n          </div>\r\n          <ScanSearch size={20} style={{ color: \"var(--sa-primary)\" }} />\r\n        </div>\r\n        <div className=\"sa-card-body\">\r\n          <DataTable\r\n            columns={deviceColumns}\r\n            data={devices}\r\n            searchKeys={[\"ip_address\", \"hostname\"]}\r\n            searchPlaceholder=\"Pesquisar por IP ou hostname...\"\r\n            rowId={(d) => d.id}\r\n            emptyMessage=\"Nenhum dispositivo cadastrado.\"\r\n          />\r\n        </div>\r\n      </div>\r\n\r\n      <div className=\"sa-card\">\r\n        <div className=\"sa-card-header\">\r\n          <div>\r\n            <h2>Jobs de scan</h2>\r\n            <p>Histórico de varreduras de portas executadas</p>\r\n          </div>\r\n        </div>\r\n        <div className=\"sa-card-body\">\r\n          <DataTable\r\n            columns={jobColumns}\r\n            data={jobs}\r\n            rowId={(j) => j.id}\r\n            pageSize={8}\r\n            emptyMessage=\"Nenhum scan executado ainda.\"\r\n          />\r\n        </div>\r\n      </div>\r\n    </>\r\n  );\r\n}\r\n",
