        "description": "Código-fonte: `frontend/src/pages/TopologyMap.tsx`",
        "file": "frontend/src/pages/TopologyMap.tsx",
        "code": "import { useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport {\n  Background,\n  ConnectionMode,\n  MiniMap,\n  Panel,\n  ReactFlow,\n  ReactFlowProvider,\n  ViewportPortal,\n  addEdge,\n  useEdgesState,\n  useNodesState,\n  useReactFlow,\n  type Connection,\n  type Edge,\n  type Node,\n  type OnConnectStart,\n  type OnNodeDrag,\n  type OnBeforeDelete,\n} from \"@xyflow/react\";\nimport dagre from \"@dagrejs/dagre\";\nimport { toPng, toSvg } from \"html-to-image\";\nimport { ChevronRight, Map, Network, RefreshCw, Save, Sparkles } from \"lucide-react\";\nimport \"@xyflow/react/dist/style.css\";\nimport \"../styles/topology-flow.css\";\nimport {\n  addDeviceOnMap,\n  addManualGroupLink,\n  addManualLink,\n  autoLayoutMap,\n  createMapGroup,\n  deleteManualGroupLink,\n  deleteManualLink,\n  deleteMapGroup,\n  discoverTopology,\n  downloadTopologyPdf,\n  downloadTopologyVisio,\n  fetchDiscoveryJobs,\n  fetchDevices,\n  fetchLinkTraffic,\n  fetchTopologyGraph,\n  fetchTopologyGroups,\n  saveTopologyLayout,\n  analyzeMapVision,\n  fetchVisionArOverlay,\n  retireDevice,\n  type TopologyGraph,\n  type VisionArOverlay,\n} from \"../api/client\";\nimport DeviceNode from \"../components/DeviceNode\";\nimport DepartmentNode from \"../components/map/DepartmentNode\";\nimport DepartmentListPanel from \"../components/map/DepartmentListPanel\";\nimport DeviceLibrary, { DEPARTMENT_DRAG_TYPE } from \"../components/map/DeviceLibrary\";\nimport GroupNode from \"../components/map/GroupNode\";\nimport MapToolbar, { type EdgeStyle, type LayoutEngine, type MapLayer, type ViewMode } from \"../components/map/MapToolbar\";\nimport CollabCursors from \"../components/map/CollabCursors\";\nimport Map3DView from \"../components/map/Map3DView\";\nimport { AlignmentGuidesOverlay, computeAlignmentGuides } from \"../components/map/AlignmentGuides\";\nimport TrafficEdge from \"../components/map/TrafficEdge\";\nimport FlowControls from \"../components/FlowControls\";\nimport { MapAddDeviceDialog, MapAddDepartmentDialog, MapConfirmDialog } from \"../components/map/MapCanvasDialog\";\nimport { useAuth } from \"../context/AuthContext\";\nimport { MapActionsProvider } from \"../context/MapActionsContext\";\nimport { useMapCollaboration } from \"../hooks/useMapCollaboration\";\nimport { useMonitoringStream } from \"../hooks/useMonitoringStream\";\nimport { layoutElk } from \"../utils/elkLayout\";\nimport { getDeviceTypeColor, getDeviceTypeLabel } from \"../constants/deviceTypes\";\nimport { MAP_CARD_HEIGHT, MAP_CARD_NODE_DIMS, MAP_CARD_WIDTH } from \"../constants/mapNodeSize\";\n\nconst nodeTypes = { device: DeviceNode, group: GroupNode, department: DepartmentNode };\nconst edgeTypes = { traffic: TrafficEdge };\n\ntype TrafficMap = Record<string, { bps_in: number; bps_out: number; util_pct?: number; source: string }>;\n\ntype AddDeviceDialogState = {\n  type: string;\n  label: string;\n  position: { x: number; y: number };\n};\n\ntype AddDepartmentDialogState = {\n  position: { x: number; y: number };\n};\n\ntype DeleteDialogState = {\n  title: string;\n  description?: string;\n  items?: string[];\n  confirmLabel?: string;\n};\n\ntype DeleteTarget = {\n  deviceLabel: string;\n  ip: string;\n};\n\nfunction deleteDialogContent(targets: DeleteTarget[]): DeleteDialogState {\n  if (targets.length === 1) {\n    const { deviceLabel, ip } = targets[0];\n    return {\n      title: `Deseja remover o dispositivo \"${deviceLabel}\" \"${ip}\" do mapa?`,\n    };\n  }\n  return {\n    title: `Deseja remover ${targets.length} dispositivos do mapa?`,\n    items: targets.map(({ deviceLabel, ip }) => `\"${deviceLabel}\" · ${ip}`),\n  };\n}\n\nfunction nodeToDeleteTarget(node: Node): DeleteTarget {\n  const deviceType = (node.data?.device_type as string) || \"unknown\";\n  const ip = String(node.data?.ip_address ?? node.data?.label ?? \"—\");\n  const name = String(node.data?.label ?? \"\");\n  const deviceLabel =\n    name && name !== ip ? name : getDeviceTypeLabel(deviceType);\n  return { deviceLabel, ip };\n}\n\nfunction edgePairKey(source: string, target: string): string {\n  return source < target ? `${source}|${target}` : `${target}|${source}`;\n}\n\nfunction isGroupNodeId(id: string): boolean {\n  return id.startsWith(\"group-\");\n}\n\nfunction isGroupEdge(edge: Edge | Connection): boolean {\n  return Boolean(\n    edge.source && edge.target && isGroupNodeId(edge.source) && isGroupNodeId(edge.target),\n  );\n}\n\nfunction resolveLinkId(edge: Edge): number | null {\n  const fromData = edge.data?.linkId;\n  if (typeof fromData === \"number\" && !Number.isNaN(fromData)) return fromData;\n  const id = String(edge.id);\n  if (id.startsWith(\"glink-\")) {\n    const parsed = parseInt(id.slice(6), 10);\n    return Number.isNaN(parsed) ? null : parsed;\n  }\n  const parsed = parseInt(id, 10);\n  return Number.isNaN(parsed) ? null : parsed;\n}\n\nfunction parseGraphEdgeLinkId(id: string): number | undefined {\n  if (id.startsWith(\"glink-\")) {\n    const parsed = parseInt(id.slice(6), 10);\n    return Number.isNaN(parsed) ? undefined : parsed;\n  }\n  const parsed = parseInt(id, 10);\n  return Number.isNaN(parsed) ? undefined : parsed;\n}\n\nconst SOURCE_HANDLES = new Set([\"right\", \"bottom\"]);\nconst TARGET_HANDLES = new Set([\"top\", \"left\"]);\n\nfunction normalizeHandle(handle: string | null | undefined, kind: \"source\" | \"target\"): string {\n  const valid = kind === \"source\" ? SOURCE_HANDLES : TARGET_HANDLES;\n  const fallback = kind === \"source\" ? \"right\" : \"left\";\n  return handle && valid.has(handle) ? handle : fallback;\n}\n\nfunction inferEdgeHandles(\n  sourceId: string,\n  targetId: string,\n  nodes: Node[],\n): { sourceHandle: string; targetHandle: string } {\n  const source = nodes.find((n) => n.id === sourceId);\n  const target = nodes.find((n) => n.id === targetId);\n  if (!source || !target) return { sourceHandle: \"right\", targetHandle: \"left\" };\n  const dx = target.position.x - source.position.x;\n  const dy = target.position.y - source.position.y;\n  if (Math.abs(dy) >= Math.abs(dx)) {\n    return dy >= 0\n      ? { sourceHandle: \"bottom\", targetHandle: \"top\" }\n      : { sourceHandle: \"right\", targetHandle: \"left\" };\n  }\n  return { sourceHandle: \"right\", targetHandle: \"left\" };\n}\n\nfunction pickConnectionHandles(\n  connection: Connection,\n  edges: Edge[],\n): { sourceHandle: string; targetHandle: string } {\n  let sourceHandle = normalizeHandle(connection.sourceHandle, \"source\");\n  let targetHandle = normalizeHandle(connection.targetHandle, \"target\");\n\n  if (\n    edges.some(\n      (e) =>\n        e.source === connection.source &&\n        e.target === connection.target &&\n        e.sourceHandle === sourceHandle &&\n        e.targetHandle === targetHandle,\n    )\n  ) {\n    return { sourceHandle, targetHandle };\n  }\n\n  if (\n    edges.some(\n      (e) => e.source === connection.source && e.sourceHandle === sourceHandle && e.target !== connection.target,\n    )\n  ) {\n    sourceHandle = sourceHandle === \"right\" ? \"bottom\" : \"right\";\n  }\n\n  if (\n    edges.some(\n      (e) => e.target === connection.target && e.targetHandle === targetHandle && e.source !== connection.source,\n    )\n  ) {\n    targetHandle = targetHandle === \"left\" ? \"top\" : \"left\";\n  }\n\n/* … truncado na árvore (arquivo completo no GitHub) … */\n",
