        "description": "Código-fonte: `frontend/src/pages/UsersPage.tsx`",
        "file": "frontend/src/pages/UsersPage.tsx",
        "code": "import { useCallback, useEffect, useState } from \"react\";\r\nimport { UserPlus } from \"lucide-react\";\r\nimport { createUser, fetchUsers, updateUser, type AdminUser } from \"../api/client\";\r\nimport DataTable, { type Column } from \"../components/ui/DataTable\";\r\nimport StatusBadge from \"../components/ui/StatusBadge\";\r\n\r\nexport default function UsersPage() {\r\n  const [users, setUsers] = useState<AdminUser[]>([]);\r\n  const [form, setForm] = useState({ username: \"\", password: \"\", role: \"viewer\" as AdminUser[\"role\"] });\r\n  const [message, setMessage] = useState<string | null>(null);\r\n\r\n  const load = useCallback(() => {\r\n    fetchUsers().then(setUsers).catch((e) => setMessage(String(e)));\r\n  }, []);\r\n\r\n  useEffect(() => {\r\n    load();\r\n  }, [load]);\r\n\r\n  const columns: Column<AdminUser>[] = [\r\n    { key: \"username\", header: \"Usuário\", render: (u) => u.username },\r\n    { key: \"role\", header: \"Role\", render: (u) => u.role },\r\n    { key: \"ldap\", header: \"LDAP\", render: (u) => (u.is_ldap ? \"Sim\" : \"Não\") },\r\n    { key: \"active\", header: \"Ativo\", render: (u) => <StatusBadge status={u.is_active ? \"active\" : \"inactive\"} /> },\r\n    {\r\n      key: \"actions\",\r\n      header: \"\",\r\n      render: (u) => (\r\n        <select\r\n          className=\"sa-input sa-input-sm\"\r\n          value={u.role}\r\n          onChange={(e) =>\r\n            updateUser(u.id, { role: e.target.value as AdminUser[\"role\"] })\r\n              .then(load)\r\n              .catch((err) => setMessage(String(err)))\r\n          }\r\n        >\r\n          <option value=\"admin\">admin</option>\r\n          <option value=\"operator\">operator</option>\r\n          <option value=\"viewer\">viewer</option>\r\n        </select>\r\n      ),\r\n    },\r\n  ];\r\n\r\n  return (\r\n    <div className=\"sa-stack\">\r\n      <section className=\"sa-card\">\r\n        <div className=\"sa-card-header\">\r\n          <h3>Novo usuário</h3>\r\n          <UserPlus size={18} />\r\n        </div>\r\n        {message && <p className=\"sa-text-muted\">{message}</p>}\r\n        <form\r\n          className=\"sa-form-row\"\r\n          onSubmit={(e) => {\r\n            e.preventDefault();\r\n            createUser(form.username, form.password, form.role)\r\n              .then(() => {\r\n                setForm({ username: \"\", password: \"\", role: \"viewer\" });\r\n                load();\r\n              })\r\n              .catch((err) => setMessage(String(err)));\r\n          }}\r\n        >\r\n          <input className=\"sa-input\" placeholder=\"Usuário\" value={form.username} onChange={(e) => setForm({ ...form, username: e.target.value })} required />\r\n          <input className=\"sa-input\" type=\"password\" placeholder=\"Senha\" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required />\r\n          <select className=\"sa-input\" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value as AdminUser[\"role\"] })}>\r\n            <option value=\"viewer\">viewer</option>\r\n            <option value=\"operator\">operator</option>\r\n            <option value=\"admin\">admin</option>\r\n          </select>\r\n          <button type=\"submit\" className=\"sa-btn sa-btn-primary\">Criar</button>\r\n        </form>\r\n      </section>\r\n      <section className=\"sa-card\">\r\n        <h3>Usuários</h3>\r\n        <DataTable columns={columns} data={users} rowId={(u) => u.id} emptyMessage=\"Nenhum usuário\" />\r\n      </section>\r\n    </div>\r\n  );\r\n}\r\n",
