        "code": "{\r\n  \"expo\": {\r\n    \"name\": \"SentinelAI\",\r\n    \"slug\": \"sentinelai-mobile\",\r\n    \"version\": \"1.3.0\",\r\n    \"orientation\": \"portrait\",\r\n    \"userInterfaceStyle\": \"dark\",\r\n    \"splash\": {\r\n      \"backgroundColor\": \"#0f172a\"\r\n    },\r\n    \"ios\": {\r\n      \"supportsTablet\": true,\r\n      \"bundleIdentifier\": \"com.sentinelai.mobile\"\r\n    },\r\n    \"android\": {\r\n      \"adaptiveIcon\": {\r\n        \"backgroundColor\": \"#0f172a\"\r\n      },\r\n      \"package\": \"com.sentinelai.mobile\"\r\n    },\r\n    \"extra\": {\r\n      \"apiUrl\": \"http://localhost:8000\"\r\n    }\r\n  }\r\n}\r\n",
